def _framework_runtime_contract_metrics(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> List[AgentReportMetricResult]:
    if not config.framework_runtime_contract:
        return []
    return [_framework_runtime_contract_metric(context, config.framework_runtime_contract)]


def _framework_runtime_contract_metric(
    context: Mapping[str, Any],
    requirements: Mapping[str, Any],
) -> AgentReportMetricResult:
    requirements = _as_dict(requirements)
    payloads = _framework_runtime_payloads_from_context(context)
    observed = _framework_runtime_summary(payloads)
    checks: List[Dict[str, Any]] = []
    findings: List[Dict[str, Any]] = []

    min_invocation_count = _as_int(
        requirements.get("min_invocation_count")
        or requirements.get("min_invocations")
        or requirements.get("invocation_count")
    )
    if min_invocation_count is not None:
        _append_framework_runtime_check(
            checks,
            findings,
            check="min_invocation_count",
            expected=min_invocation_count,
            actual=observed["invocation_count"],
            match=observed["invocation_count"] >= min_invocation_count,
            finding_type="framework_runtime_invocation_count_low",
        )

    expected_framework = requirements.get("framework") or requirements.get("required_framework")
    if expected_framework not in (None, "", [], {}):
        normalized = _normalize_framework_runtime_key(expected_framework)
        _append_framework_runtime_check(
            checks,
            findings,
            check="framework",
            expected=normalized,
            actual=observed["frameworks"],
            match=normalized in observed["frameworks"],
            finding_type="framework_runtime_framework_mismatch",
        )

    expected_method = requirements.get("method") or requirements.get("required_method")
    if expected_method not in (None, "", [], {}):
        normalized = _normalize_framework_runtime_key(expected_method)
        _append_framework_runtime_check(
            checks,
            findings,
            check="method",
            expected=normalized,
            actual=observed["methods"],
            match=normalized in observed["methods"],
            finding_type="framework_runtime_method_missing",
        )

    expected_input_mode = requirements.get("input_mode") or requirements.get("required_input_mode")
    if expected_input_mode not in (None, "", [], {}):
        normalized = _normalize_framework_runtime_key(expected_input_mode)
        _append_framework_runtime_check(
            checks,
            findings,
            check="input_mode",
            expected=normalized,
            actual=observed["input_modes"],
            match=normalized in observed["input_modes"],
            finding_type="framework_runtime_input_mode_mismatch",
        )

    expected_input_key = requirements.get("input_key") or requirements.get("required_input_key")
    if expected_input_key not in (None, "", [], {}):
        normalized = _normalize_framework_runtime_key(expected_input_key)
        _append_framework_runtime_check(
            checks,
            findings,
            check="input_key",
            expected=normalized,
            actual=observed["input_keys"],
            match=normalized in observed["input_keys"],
            finding_type="framework_runtime_input_key_missing",
        )

    expected_call_style = requirements.get("call_style") or requirements.get("required_call_style")
    if expected_call_style not in (None, "", [], {}):
        normalized = _normalize_framework_runtime_key(expected_call_style)
        _append_framework_runtime_check(
            checks,
            findings,
            check="call_style",
            expected=normalized,
            actual=observed["call_styles"],
            match=normalized in observed["call_styles"],
            finding_type="framework_runtime_call_style_missing",
        )

    for key in _string_list(
        requirements.get("input_kwargs_keys")
        or requirements.get("required_input_kwargs")
        or requirements.get("required_input_kwargs_keys")
    ):
        normalized = _normalize_framework_runtime_key(key)
        _append_framework_runtime_check(
            checks,
            findings,
            check="input_kwargs_key",
            expected=normalized,
            actual=observed["input_kwargs_keys"],
            match=normalized in observed["input_kwargs_keys"],
            finding_type="framework_runtime_input_kwarg_missing",
        )

    for signal in _string_list(requirements.get("required_signals") or requirements.get("signals")):
        normalized = _normalize_framework_runtime_key(signal)
        _append_framework_runtime_check(
            checks,
            findings,
            check="signal",
            expected=normalized,
            actual=observed["signals"],
            match=normalized in observed["signals"],
            finding_type="framework_runtime_signal_missing",
        )

    for tool in _string_list(requirements.get("required_tools") or requirements.get("tools")):
        normalized = _normalize_framework_runtime_key(tool)
        _append_framework_runtime_check(
            checks,
            findings,
            check="tool",
            expected=normalized,
            actual=observed["tool_names"],
            match=normalized in observed["tool_names"],
            finding_type="framework_runtime_tool_missing",
        )

    for artifact_type in _string_list(requirements.get("required_artifact_types") or requirements.get("artifact_types")):
        normalized = _normalize_framework_runtime_key(artifact_type)
        _append_framework_runtime_check(
            checks,
            findings,
            check="artifact_type",
            expected=normalized,
            actual=observed["artifact_types"],
            match=normalized in observed["artifact_types"],
            finding_type="framework_runtime_artifact_missing",
        )

    for event_type in _string_list(requirements.get("required_event_types") or requirements.get("event_types")):
        normalized = _normalize_framework_runtime_key(event_type)
        _append_framework_runtime_check(
            checks,
            findings,
            check="event_type",
            expected=normalized,
            actual=observed["event_types"],
            match=normalized in observed["event_types"],
            finding_type="framework_runtime_event_missing",
        )

    for state_key in _string_list(requirements.get("required_state_keys") or requirements.get("state_keys")):
        normalized = _normalize_framework_runtime_key(state_key)
        _append_framework_runtime_check(
            checks,
            findings,
            check="state_key",
            expected=normalized,
            actual=observed["state_keys"],
            match=normalized in observed["state_keys"],
            finding_type="framework_runtime_state_key_missing",
        )

    for metadata_key in _string_list(requirements.get("required_metadata_keys") or requirements.get("metadata_keys")):
        normalized = _normalize_framework_runtime_key(metadata_key)
        _append_framework_runtime_check(
            checks,
            findings,
            check="metadata_key",
            expected=normalized,
            actual=observed["metadata_keys"],
            match=normalized in observed["metadata_keys"],
            finding_type="framework_runtime_metadata_missing",
        )

    if requirements.get("require_streaming") is not None:
        required = bool(requirements.get("require_streaming"))
        _append_framework_runtime_check(
            checks,
            findings,
            check="streaming",
            expected=required,
            actual=observed["streamed"],
            match=observed["streamed"] is required,
            finding_type="framework_runtime_streaming_mismatch",
        )

    max_error_count = _as_int(requirements.get("max_error_count") or requirements.get("max_errors"))
    if max_error_count is not None:
        _append_framework_runtime_check(
            checks,
            findings,
            check="max_error_count",
            expected=max_error_count,
            actual=observed["error_count"],
            match=observed["error_count"] <= max_error_count,
            finding_type="framework_runtime_error_count_high",
        )

    if not checks:
        return AgentReportMetricResult(
            name="framework_runtime_contract",
            score=1.0,
            reason="No framework runtime contract checks were configured.",
        )

    matched = sum(1 for check in checks if check["match"])
    return AgentReportMetricResult(
        name="framework_runtime_contract",
        score=round(matched / len(checks), 4),
        reason=f"{matched}/{len(checks)} framework runtime contract check(s) matched.",
        details={
            "checks": checks,
            "findings": findings,
            "observed": observed,
        },
    )


def _framework_adapter_call_contract_quality_metrics(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> List[AgentReportMetricResult]:
    metric_name = "framework_adapter_call_contract_quality"
    if not config.framework_adapter_call_contract_quality and (
        metric_name not in config.metric_weights
    ):
        return []
    return [
        _framework_adapter_call_contract_quality_metric(
            context,
            config.framework_adapter_call_contract_quality,
        )
    ]


def _framework_adapter_call_contract_quality_metric(
    context: Mapping[str, Any],
    requirements: Mapping[str, Any],
) -> AgentReportMetricResult:
    metric_name = "framework_adapter_call_contract_quality"
    requirements = _as_dict(requirements)
    contracts = _framework_adapter_call_contracts_from_context(context)
    observed = _framework_adapter_call_contract_summary(contracts)
    checks: List[Dict[str, Any]] = []
    findings: List[Dict[str, Any]] = []

    min_contract_count = _as_int(
        requirements.get("min_contract_count")
        or requirements.get("min_call_contract_count")
        or requirements.get("min_invocation_count")
    )
    if min_contract_count is None:
        min_contract_count = 1
    _append_framework_adapter_runtime_contract_check(
        checks,
        findings,
        metric=metric_name,
        check="min_contract_count",
        expected={">=": min_contract_count},
        actual=observed["contract_count"],
        match=observed["contract_count"] >= min_contract_count,
        finding_type="framework_adapter_call_contract_count_low",
    )

    expected_kind = (
        requirements.get("kind")
        or "agent-learning.framework-adapter-call-contract.v1"
    )
    normalized_kind = _normalize_framework_adapter_io_key(expected_kind)
    _append_framework_adapter_runtime_contract_check(
        checks,
        findings,
        metric=metric_name,
        check="kind",
        expected=normalized_kind,
        actual=observed["kinds"],
        match=normalized_kind in observed["kinds"],
        finding_type="framework_adapter_call_contract_kind_missing",
    )

    for requirement_key, observed_key, finding_type in (
        ("framework", "frameworks", "framework_adapter_call_contract_framework_mismatch"),
        ("method", "methods", "framework_adapter_call_contract_method_missing"),
        ("input_mode", "input_modes", "framework_adapter_call_contract_input_mode_mismatch"),
        ("input_key", "input_keys", "framework_adapter_call_contract_input_key_missing"),
        ("call_style", "call_styles", "framework_adapter_call_contract_call_style_missing"),
    ):
        expected = requirements.get(requirement_key) or requirements.get(
            f"required_{requirement_key}"
        )
        if expected in (None, "", [], {}):
            continue
        normalized = _normalize_framework_adapter_io_key(expected)
        _append_framework_adapter_runtime_contract_check(
            checks,
            findings,
            metric=metric_name,
            check=requirement_key,
            expected=normalized,
            actual=observed[observed_key],
            match=normalized in observed[observed_key],
            finding_type=finding_type,
        )

    for requirement_key, observed_key, finding_type in (
        ("required_frameworks", "frameworks", "framework_adapter_call_contract_framework_mismatch"),
        ("required_methods", "methods", "framework_adapter_call_contract_method_missing"),
        ("required_input_modes", "input_modes", "framework_adapter_call_contract_input_mode_mismatch"),
        ("required_input_keys", "input_keys", "framework_adapter_call_contract_input_key_missing"),
        ("required_call_styles", "call_styles", "framework_adapter_call_contract_call_style_missing"),
        ("required_input_kwargs", "input_kwargs_keys", "framework_adapter_call_contract_input_kwarg_missing"),
        ("required_input_kwargs_keys", "input_kwargs_keys", "framework_adapter_call_contract_input_kwarg_missing"),
        ("input_kwargs_keys", "input_kwargs_keys", "framework_adapter_call_contract_input_kwarg_missing"),
        ("required_parameter_names", "parameter_names", "framework_adapter_call_contract_parameter_missing"),
        ("required_keyword_only_parameters", "keyword_only_parameters", "framework_adapter_call_contract_keyword_only_missing"),
    ):
        for expected in _string_list(requirements.get(requirement_key)):
            normalized = _normalize_framework_adapter_io_key(expected)
            _append_framework_adapter_runtime_contract_check(
                checks,
                findings,
                metric=metric_name,
                check=requirement_key,
                expected=normalized,
                actual=observed[observed_key],
                match=normalized in observed[observed_key],
                finding_type=finding_type,
            )

    if (
        requirements.get("require_signature")
        is not None
        or requirements.get("require_callable_signature") is not None
    ):
        required = bool(
            requirements.get(
                "require_signature",
                requirements.get("require_callable_signature"),
            )
        )
        _append_framework_adapter_runtime_contract_check(
            checks,
            findings,
            metric=metric_name,
            check="require_signature",
            expected=required,
            actual=observed["signature_count"],
            match=(observed["signature_count"] >= min_contract_count)
            if required
            else True,
            finding_type="framework_adapter_call_contract_signature_missing",
        )

    if (
        requirements.get("require_signature_inspectable")
        is not None
        or requirements.get("require_inspectable_signature") is not None
    ):
        required = bool(
            requirements.get(
                "require_signature_inspectable",
                requirements.get("require_inspectable_signature"),
            )
        )
        _append_framework_adapter_runtime_contract_check(
            checks,
            findings,
            metric=metric_name,
            check="require_signature_inspectable",
            expected=required,
            actual=observed["signature_inspectable_count"],
            match=(observed["signature_inspectable_count"] >= min_contract_count)
            if required
            else True,
            finding_type="framework_adapter_call_contract_signature_uninspectable",
        )

    if requirements.get("require_signature_bound") is not None:
        required = bool(requirements.get("require_signature_bound"))
        _append_framework_adapter_runtime_contract_check(
            checks,
            findings,
            metric=metric_name,
            check="require_signature_bound",
            expected=required,
            actual=observed["signature_bound_count"],
            match=(observed["signature_bound_count"] >= min_contract_count)
            if required
            else True,
            finding_type="framework_adapter_call_contract_signature_unbound",
        )

    max_error_count = _as_int(
        requirements.get("max_error_count") or requirements.get("max_errors")
    )
    if max_error_count is not None:
        _append_framework_adapter_runtime_contract_check(
            checks,
            findings,
            metric=metric_name,
            check="max_error_count",
            expected=max_error_count,
            actual=observed["error_count"],
            match=observed["error_count"] <= max_error_count,
            finding_type="framework_adapter_call_contract_error_count_high",
        )

    matched = sum(1 for check in checks if check["match"])
    return AgentReportMetricResult(
        name=metric_name,
        score=round(matched / len(checks), 4) if checks else 1.0,
        reason=(
            f"{matched}/{len(checks)} framework adapter call-contract "
            "check(s) matched."
            if checks
            else "No framework adapter call-contract checks were configured."
        ),
        details={
            "checks": checks,
            "findings": findings,
            "observed": observed,
        },
    )


def _framework_adapter_observed_io_quality_metrics(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> List[AgentReportMetricResult]:
    metric_name = "framework_adapter_observed_io_quality"
    if not config.framework_adapter_observed_io_quality and (
        metric_name not in config.metric_weights
    ):
        return []
    return [
        _framework_adapter_observed_io_quality_metric(
            context,
            config.framework_adapter_observed_io_quality,
        )
    ]


def _framework_adapter_observed_io_quality_metric(
    context: Mapping[str, Any],
    requirements: Mapping[str, Any],
) -> AgentReportMetricResult:
    metric_name = "framework_adapter_observed_io_quality"
    requirements = _as_dict(requirements)
    contracts = _framework_adapter_observed_io_contracts_from_context(context)
    observed = _framework_adapter_observed_io_summary(contracts)
    checks: List[Dict[str, Any]] = []
    findings: List[Dict[str, Any]] = []

    min_contract_count = _as_int(
        requirements.get("min_contract_count")
        or requirements.get("min_observed_io_count")
        or requirements.get("min_observed_io_contract_count")
    )
    if min_contract_count is None:
        min_contract_count = 1
    _append_framework_adapter_runtime_contract_check(
        checks,
        findings,
        metric=metric_name,
        check="min_contract_count",
        expected={">=": min_contract_count},
        actual=observed["contract_count"],
        match=observed["contract_count"] >= min_contract_count,
        finding_type="framework_adapter_observed_io_contract_count_low",
    )

    min_invocation_count = _as_int(
        requirements.get("min_invocation_count")
        or requirements.get("min_invocations")
    )
    if min_invocation_count is not None:
        _append_framework_adapter_runtime_contract_check(
            checks,
            findings,
            metric=metric_name,
            check="min_invocation_count",
            expected={">=": min_invocation_count},
            actual=observed["invocation_count"],
            match=observed["invocation_count"] >= min_invocation_count,
            finding_type="framework_adapter_observed_io_invocation_count_low",
        )

    expected_kind = (
        requirements.get("kind")
        or "agent-learning.framework-adapter-observed-io-contract.v1"
    )
    normalized_kind = _normalize_framework_adapter_io_key(expected_kind)
    _append_framework_adapter_runtime_contract_check(
        checks,
        findings,
        metric=metric_name,
        check="kind",
        expected=normalized_kind,
        actual=observed["kinds"],
        match=normalized_kind in observed["kinds"],
        finding_type="framework_adapter_observed_io_kind_missing",
    )

    for requirement_key, observed_key, finding_type in (
        ("framework", "frameworks", "framework_adapter_observed_io_framework_mismatch"),
        ("method", "methods", "framework_adapter_observed_io_method_missing"),
        ("input_mode", "input_modes", "framework_adapter_observed_io_input_mode_mismatch"),
    ):
        expected = requirements.get(requirement_key) or requirements.get(
            f"required_{requirement_key}"
        )
        if expected in (None, "", [], {}):
            continue
        normalized = _normalize_framework_adapter_io_key(expected)
        _append_framework_adapter_runtime_contract_check(
            checks,
            findings,
            metric=metric_name,
            check=requirement_key,
            expected=normalized,
            actual=observed[observed_key],
            match=normalized in observed[observed_key],
            finding_type=finding_type,
        )

    for requirement_key, observed_key, finding_type in (
        ("required_frameworks", "frameworks", "framework_adapter_observed_io_framework_mismatch"),
        ("required_methods", "methods", "framework_adapter_observed_io_method_missing"),
        ("required_input_modes", "input_modes", "framework_adapter_observed_io_input_mode_mismatch"),
        ("required_call_styles", "call_styles", "framework_adapter_observed_io_call_style_missing"),
        ("required_input_keys", "input_keys", "framework_adapter_observed_io_input_key_missing"),
        ("required_input_kwargs", "input_kwargs_keys", "framework_adapter_observed_io_input_kwarg_missing"),
        ("required_input_kwargs_keys", "input_kwargs_keys", "framework_adapter_observed_io_input_kwarg_missing"),
        ("required_input_types", "input_types", "framework_adapter_observed_io_input_type_missing"),
        ("required_output_types", "output_types", "framework_adapter_observed_io_output_type_missing"),
        ("required_output_state_keys", "output_state_keys", "framework_adapter_observed_io_state_key_missing"),
        ("required_output_metadata_keys", "output_metadata_keys", "framework_adapter_observed_io_metadata_key_missing"),
        ("required_output_tool_names", "output_tool_names", "framework_adapter_observed_io_tool_missing"),
        ("required_output_event_types", "output_event_types", "framework_adapter_observed_io_event_missing"),
        ("required_output_artifact_types", "output_artifact_types", "framework_adapter_observed_io_artifact_missing"),
    ):
        for expected in _string_list(requirements.get(requirement_key)):
            normalized = _normalize_framework_adapter_io_key(expected)
            _append_framework_adapter_runtime_contract_check(
                checks,
                findings,
                metric=metric_name,
                check=requirement_key,
                expected=normalized,
                actual=observed[observed_key],
                match=normalized in observed[observed_key],
                finding_type=finding_type,
            )

    if requirements.get("require_content_observed") is not None:
        required = bool(requirements.get("require_content_observed"))
        _append_framework_adapter_runtime_contract_check(
            checks,
            findings,
            metric=metric_name,
            check="require_content_observed",
            expected=required,
            actual=observed["content_observed_count"],
            match=(observed["content_observed_count"] >= min_contract_count)
            if required
            else True,
            finding_type="framework_adapter_observed_io_content_missing",
        )

    if requirements.get("require_signature_bound") is not None:
        required = bool(requirements.get("require_signature_bound"))
        _append_framework_adapter_runtime_contract_check(
            checks,
            findings,
            metric=metric_name,
            check="require_signature_bound",
            expected=required,
            actual=observed["signature_bound_count"],
            match=(observed["signature_bound_count"] >= min_contract_count)
            if required
            else True,
            finding_type="framework_adapter_observed_io_signature_unbound",
        )

    max_error_count = _as_int(
        requirements.get("max_error_count") or requirements.get("max_errors")
    )
    if max_error_count is not None:
        _append_framework_adapter_runtime_contract_check(
            checks,
            findings,
            metric=metric_name,
            check="max_error_count",
            expected=max_error_count,
            actual=observed["error_count"],
            match=observed["error_count"] <= max_error_count,
            finding_type="framework_adapter_observed_io_error_count_high",
        )

    matched = sum(1 for check in checks if check["match"])
    return AgentReportMetricResult(
        name=metric_name,
        score=round(matched / len(checks), 4) if checks else 1.0,
        reason=(
            f"{matched}/{len(checks)} framework adapter observed-I/O "
            "check(s) matched."
            if checks
            else "No framework adapter observed-I/O checks were configured."
        ),
        details={
            "checks": checks,
            "findings": findings,
            "observed": observed,
        },
    )


def _framework_adapter_contract_quality_metrics(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> List[AgentReportMetricResult]:
    if not config.framework_adapter_contract_quality:
        return []
    return [
        _framework_adapter_contract_quality_metric(
            context,
            config.framework_adapter_contract_quality,
        )
    ]


def _framework_adapter_contract_quality_metric(
    context: Mapping[str, Any],
    requirements: Mapping[str, Any],
) -> AgentReportMetricResult:
    requirements = _as_dict(requirements)
    contracts = _framework_adapter_contracts_from_context(context)
    observed = _framework_adapter_contract_summary(contracts)
    checks: List[Dict[str, Any]] = []
    findings: List[Dict[str, Any]] = []

    _append_framework_adapter_contract_check(
        checks,
        findings,
        check="contract_present",
        expected={">=": 1},
        actual=observed["contract_count"],
        match=observed["contract_count"] >= 1,
        finding_type="framework_adapter_contract_missing",
    )

    expected_kind = requirements.get("kind") or "agent-learning.framework-adapter-contract.v1"
    _append_framework_adapter_contract_check(
        checks,
        findings,
        check="kind",
        expected=str(expected_kind),
        actual=observed["kinds"],
        match=str(expected_kind).lower() in observed["kinds"],
        finding_type="framework_adapter_contract_kind_missing",
    )

    scalar_checks = (
        ("framework", "frameworks", "framework_adapter_contract_framework_mismatch"),
        ("method", "methods", "framework_adapter_contract_method_missing"),
        ("input_mode", "input_modes", "framework_adapter_contract_input_mode_mismatch"),
        ("modality", "modalities", "framework_adapter_contract_modality_mismatch"),
        ("transport", "transports", "framework_adapter_contract_transport_mismatch"),
        ("adapter", "adapters", "framework_adapter_contract_adapter_mismatch"),
    )
    for requirement_key, observed_key, finding_type in scalar_checks:
        expected = requirements.get(requirement_key) or requirements.get(
            f"required_{requirement_key}"
        )
        if expected in (None, "", [], {}):
            continue
        normalized = _normalize_framework_adapter_contract_key(expected)
        _append_framework_adapter_contract_check(
            checks,
            findings,
            check=requirement_key,
            expected=normalized,
            actual=observed[observed_key],
            match=normalized in observed[observed_key],
            finding_type=finding_type,
        )

    plural_scalar_checks = (
        (
            "required_frameworks",
            "frameworks",
            "framework_adapter_contract_framework_mismatch",
        ),
        ("required_methods", "methods", "framework_adapter_contract_method_missing"),
        (
            "required_input_modes",
            "input_modes",
            "framework_adapter_contract_input_mode_mismatch",
        ),
        (
            "required_modalities",
            "modalities",
            "framework_adapter_contract_modality_mismatch",
        ),
        (
            "required_transports",
            "transports",
            "framework_adapter_contract_transport_mismatch",
        ),
        ("required_adapters", "adapters", "framework_adapter_contract_adapter_mismatch"),
    )
    for requirement_key, observed_key, finding_type in plural_scalar_checks:
        for expected in _string_list(requirements.get(requirement_key)):
            normalized = _normalize_framework_adapter_contract_key(expected)
            _append_framework_adapter_contract_check(
                checks,
                findings,
                check=requirement_key,
                expected=normalized,
                actual=observed[observed_key],
                match=normalized in observed[observed_key],
                finding_type=finding_type,
            )

    bool_checks = (
        (
            "require_trace_runtime",
            "trace_runtime_values",
            True,
            "framework_adapter_contract_trace_runtime_missing",
        ),
        (
            "require_local_executable_fixture",
            "local_executable_fixture_values",
            True,
            "framework_adapter_contract_local_fixture_missing",
        ),
    )
    for requirement_key, observed_key, expected, finding_type in bool_checks:
        if requirements.get(requirement_key) is None:
            continue
        required = bool(requirements.get(requirement_key))
        _append_framework_adapter_contract_check(
            checks,
            findings,
            check=requirement_key,
            expected=required,
            actual=observed[observed_key],
            match=(required in observed[observed_key]) if required else True,
            finding_type=finding_type,
        )

    if requirements.get("require_no_external_service") is not None:
        required = bool(requirements.get("require_no_external_service"))
        actual_values = observed["requires_external_service_values"]
        external_present = True in actual_values
        local_declared = False in actual_values
        _append_framework_adapter_contract_check(
            checks,
            findings,
            check="require_no_external_service",
            expected=required,
            actual=actual_values,
            match=(local_declared and not external_present) if required else True,
            finding_type="framework_adapter_contract_external_service_required",
        )

    if requirements.get("require_target") is not None:
        required = bool(requirements.get("require_target"))
        _append_framework_adapter_contract_check(
            checks,
            findings,
            check="require_target",
            expected=required,
            actual=observed["target_count"],
            match=(observed["target_count"] >= 1) if required else True,
            finding_type="framework_adapter_contract_target_missing",
        )

    forbidden_schemes = {
        _normalize_framework_adapter_contract_key(value)
        for value in _string_list(
            requirements.get("forbidden_target_schemes")
            or (["http", "https"] if requirements.get("require_no_external_service") else [])
        )
    }
    if forbidden_schemes:
        present = sorted(forbidden_schemes & set(observed["target_schemes"]))
        _append_framework_adapter_contract_check(
            checks,
            findings,
            check="forbidden_target_schemes",
            expected={"absent": sorted(forbidden_schemes)},
            actual=observed["target_schemes"],
            match=not present,
            finding_type="framework_adapter_contract_external_target_scheme",
        )

    list_checks = (
        (
            "required_capabilities",
            "capabilities",
            "framework_adapter_contract_capability_missing",
        ),
        (
            "required_evidence_requirements",
            "evidence_requirements",
            "framework_adapter_contract_evidence_requirement_missing",
        ),
        (
            "required_lifecycle_hooks",
            "lifecycle_hooks",
            "framework_adapter_contract_lifecycle_hook_missing",
        ),
        (
            "required_schema_sections",
            "schema_sections",
            "framework_adapter_contract_schema_section_missing",
        ),
    )
    for requirement_key, observed_key, finding_type in list_checks:
        for expected in _string_list(requirements.get(requirement_key)):
            normalized = _normalize_framework_adapter_contract_key(expected)
            _append_framework_adapter_contract_check(
                checks,
                findings,
                check=requirement_key,
                expected=normalized,
                actual=observed[observed_key],
                match=normalized in observed[observed_key],
                finding_type=finding_type,
            )

    if not checks:
        return AgentReportMetricResult(
            name="framework_adapter_contract_quality",
            score=1.0,
            reason="No framework adapter contract quality checks were configured.",
        )

    matched = sum(1 for check in checks if check["match"])
    return AgentReportMetricResult(
        name="framework_adapter_contract_quality",
        score=round(matched / len(checks), 4),
        reason=(
            f"{matched}/{len(checks)} framework adapter contract "
            "quality check(s) matched."
        ),
        details={
            "checks": checks,
            "findings": findings,
            "observed": observed,
        },
    )


def _framework_lifecycle_coverage_metrics(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> List[AgentReportMetricResult]:
    if not config.required_framework_lifecycle and not _framework_lifecycle_payloads_from_context(context):
        return []
    return [_framework_lifecycle_coverage_metric(context, config)]


def _framework_lifecycle_coverage_metric(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> AgentReportMetricResult:
    required = [_normalize_framework_lifecycle_key(key) for key in config.required_framework_lifecycle]
    required = [key for key in required if key]
    if not required:
        return AgentReportMetricResult(
            name="framework_lifecycle_coverage",
            score=1.0,
            reason="No required framework lifecycle keys provided.",
        )
    observed = _framework_lifecycle_observed(context)
    missing = sorted(set(required) - observed)
    matched = len(set(required) - set(missing))
    return AgentReportMetricResult(
        name="framework_lifecycle_coverage",
        score=round(matched / len(set(required)), 4),
        reason=(
            "All required framework lifecycle evidence observed."
            if not missing
            else f"Missing framework lifecycle evidence: {', '.join(missing)}."
        ),
        details={
            "required": sorted(set(required)),
            "observed": sorted(observed),
            "missing": missing,
            "findings": [
                {"type": "missing_framework_lifecycle_key", "key": key}
                for key in missing
            ],
        },
    )


def _framework_lifecycle_quality_metrics(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> List[AgentReportMetricResult]:
    if not config.framework_lifecycle_quality:
        return []
    return [_framework_lifecycle_quality_metric(context, config.framework_lifecycle_quality)]


def _framework_lifecycle_quality_metric(
    context: Mapping[str, Any],
    requirements: Mapping[str, Any],
) -> AgentReportMetricResult:
    requirements = _as_dict(requirements)
    observed = _framework_lifecycle_summary(_framework_lifecycle_payloads_from_context(context))
    checks: List[Dict[str, Any]] = []
    findings: List[Dict[str, Any]] = []

    min_phase_count = _as_int(requirements.get("min_phase_count") or requirements.get("min_phases"))
    if min_phase_count is not None:
        _append_framework_lifecycle_check(
            checks,
            findings,
            check="min_phase_count",
            expected=min_phase_count,
            actual=observed["phase_count"],
            match=observed["phase_count"] >= min_phase_count,
            finding_type="framework_lifecycle_phase_count_low",
        )

    expected_framework = requirements.get("framework") or requirements.get("required_framework")
    if expected_framework not in (None, "", [], {}):
        normalized = _normalize_framework_lifecycle_key(expected_framework)
        _append_framework_lifecycle_check(
            checks,
            findings,
            check="framework",
            expected=normalized,
            actual=observed["frameworks"],
            match=normalized in observed["frameworks"],
            finding_type="framework_lifecycle_framework_mismatch",
        )

    for session in _string_list(requirements.get("required_sessions") or requirements.get("sessions")):
        expected = str(session)
        _append_framework_lifecycle_check(
            checks,
            findings,
            check="session",
            expected=expected,
            actual=observed["sessions"],
            match=expected in observed["sessions"],
            finding_type="framework_lifecycle_session_missing",
        )

    for stage in _string_list(requirements.get("required_stages") or requirements.get("stages")):
        normalized = _normalize_framework_lifecycle_stage(stage)
        _append_framework_lifecycle_check(
            checks,
            findings,
            check="stage",
            expected=normalized,
            actual=observed["stages"],
            match=normalized in observed["stages"],
            finding_type="framework_lifecycle_stage_missing",
        )

    for signal in _string_list(requirements.get("required_signals") or requirements.get("signals")):
        normalized = _normalize_framework_lifecycle_key(signal)
        _append_framework_lifecycle_check(
            checks,
            findings,
            check="signal",
            expected=normalized,
            actual=observed["signals"],
            match=normalized in observed["signals"],
            finding_type="framework_lifecycle_signal_missing",
        )

    count_checks = (
        ("min_tool_registrations", "tool_registration_count", "framework_lifecycle_tool_registration_low"),
        ("min_invocations", "invocation_count", "framework_lifecycle_invocation_count_low"),
        ("min_recovered_errors", "recovered_error_count", "framework_lifecycle_recovery_count_low"),
    )
    for key, observed_key, finding_type in count_checks:
        expected = _as_int(requirements.get(key))
        if expected is None:
            continue
        _append_framework_lifecycle_check(
            checks,
            findings,
            check=key,
            expected=expected,
            actual=observed[observed_key],
            match=observed[observed_key] >= expected,
            finding_type=finding_type,
        )

    bool_checks = (
        ("require_streaming", "has_streaming", "framework_lifecycle_streaming_missing"),
        ("require_checkpoint", "has_checkpoint", "framework_lifecycle_checkpoint_missing"),
        ("require_retry", "has_retry", "framework_lifecycle_retry_missing"),
        ("require_cancellation", "has_cancellation", "framework_lifecycle_cancellation_missing"),
        ("require_cancel", "has_cancellation", "framework_lifecycle_cancellation_missing"),
        ("require_resume", "has_resume", "framework_lifecycle_resume_missing"),
        ("require_cleanup", "has_cleanup", "framework_lifecycle_cleanup_missing"),
        ("require_state_persistence", "state_persistence", "framework_lifecycle_state_persistence_missing"),
    )
    for key, observed_key, finding_type in bool_checks:
        if requirements.get(key) is None:
            continue
        required = bool(requirements.get(key))
        _append_framework_lifecycle_check(
            checks,
            findings,
            check=key,
            expected=required,
            actual=observed[observed_key],
            match=observed[observed_key] is required,
            finding_type=finding_type,
        )

    terminal_status = requirements.get("terminal_status") or requirements.get("required_terminal_status")
    if terminal_status not in (None, "", [], {}):
        normalized = _normalize_framework_lifecycle_key(terminal_status)
        _append_framework_lifecycle_check(
            checks,
            findings,
            check="terminal_status",
            expected=normalized,
            actual=observed["terminal_status"],
            match=observed["terminal_status"] == normalized,
            finding_type="framework_lifecycle_terminal_status_mismatch",
        )

    max_error_count = _as_int(requirements.get("max_error_count") or requirements.get("max_errors"))
    if max_error_count is not None:
        _append_framework_lifecycle_check(
            checks,
            findings,
            check="max_error_count",
            expected=max_error_count,
            actual=observed["error_count"],
            match=observed["error_count"] <= max_error_count,
            finding_type="framework_lifecycle_error_count_high",
        )

    if not checks:
        return AgentReportMetricResult(
            name="framework_lifecycle_quality",
            score=1.0,
            reason="No framework lifecycle quality checks were configured.",
        )

    matched = sum(1 for check in checks if check["match"])
    return AgentReportMetricResult(
        name="framework_lifecycle_quality",
        score=round(matched / len(checks), 4),
        reason=f"{matched}/{len(checks)} framework lifecycle quality check(s) matched.",
        details={
            "checks": checks,
            "findings": findings,
            "observed": observed,
        },
    )


def _framework_adapter_conformance_metrics(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> List[AgentReportMetricResult]:
    if not config.framework_adapter_conformance:
        return []
    return [_framework_adapter_conformance_metric(context, config.framework_adapter_conformance)]


def _framework_adapter_conformance_metric(
    context: Mapping[str, Any],
    requirements: Mapping[str, Any],
) -> AgentReportMetricResult:
    requirements = _as_dict(requirements)

    records = _framework_trace_records_from_context(context)
    payloads = _framework_trace_payloads_from_context(context)
    required_signals = [
        _normalize_framework_trace_key(signal)
        for signal in _string_list(
            requirements.get("required_signals")
            or requirements.get("signals")
            or requirements.get("required_trace_signals")
        )
    ]
    required_signals = [signal for signal in required_signals if signal]
    required_mappings = _framework_adapter_required_mappings(
        requirements.get("required_mappings")
        or requirements.get("mappings")
        or requirements.get("field_mappings")
        or {}
    )
    observed_signals = _framework_adapter_observed_signals(records, payloads)
    checks: List[Dict[str, Any]] = []
    findings: List[Dict[str, Any]] = []

    for signal in required_signals:
        matched = signal in observed_signals
        _append_framework_adapter_check(
            checks,
            findings,
            check="signal",
            signal=signal,
            path=None,
            matched=matched,
            finding_type="framework_adapter_signal_missing",
            observed=sorted(observed_signals),
        )

    for signal, paths in required_mappings.items():
        signal_records = [
            record
            for record in records
            if signal in {
                _normalize_framework_trace_key(item)
                for item in _as_list(record.get("signals", []))
            }
        ]
        for path in paths:
            matching_records = [
                str(record.get("id") or record.get("span_id") or record.get("name") or "")
                for record in signal_records
                if _framework_adapter_record_has_path(record, path)
            ]
            _append_framework_adapter_check(
                checks,
                findings,
                check="mapping",
                signal=signal,
                path=path,
                matched=bool(matching_records),
                finding_type="framework_adapter_mapping_missing",
                observed=[item for item in matching_records if item],
            )

    if not checks:
        return AgentReportMetricResult(
            name="framework_adapter_conformance",
            score=1.0,
            reason="No framework adapter conformance checks were configured.",
        )

    matched = sum(1 for check in checks if check["matched"])
    return AgentReportMetricResult(
        name="framework_adapter_conformance",
        score=round(matched / len(checks), 4),
        reason=f"{matched}/{len(checks)} framework adapter conformance check(s) matched.",
        details={
            "checks": checks,
            "findings": findings,
            "observed": {"signals": sorted(observed_signals)},
        },
    )


def _framework_capability_coverage_metrics(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> List[AgentReportMetricResult]:
    if not config.required_framework_capabilities and not _framework_capability_payloads_from_context(context):
        return []
    return [_framework_capability_coverage_metric(context, config)]


def _framework_capability_coverage_metric(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> AgentReportMetricResult:
    required = [_normalize_framework_capability_key(key) for key in config.required_framework_capabilities]
    required = [key for key in required if key]
    if not required:
        return AgentReportMetricResult(
            name="framework_capability_coverage",
            score=1.0,
            reason="No required framework capability keys provided.",
        )
    observed = _framework_capability_observed(context)
    missing = sorted(set(required) - observed)
    matched = len(set(required) - set(missing))
    return AgentReportMetricResult(
        name="framework_capability_coverage",
        score=round(matched / len(set(required)), 4),
        reason=(
            "All required framework capability evidence observed."
            if not missing
            else f"Missing framework capability evidence: {', '.join(missing)}."
        ),
        details={
            "required": sorted(set(required)),
            "observed": sorted(observed),
            "missing": missing,
            "findings": [
                {"type": "missing_framework_capability_key", "key": key}
                for key in missing
            ],
        },
    )


def _framework_capability_quality_metrics(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> List[AgentReportMetricResult]:
    if not config.framework_capability_quality:
        return []
    return [_framework_capability_quality_metric(context, config.framework_capability_quality)]


def _framework_capability_quality_metric(
    context: Mapping[str, Any],
    requirements: Mapping[str, Any],
) -> AgentReportMetricResult:
    requirements = _as_dict(requirements)
    observed = _framework_capability_summary(_framework_capability_payloads_from_context(context))
    checks: List[Dict[str, Any]] = []
    findings: List[Dict[str, Any]] = []

    expected_framework = requirements.get("framework") or requirements.get("required_framework")
    if expected_framework not in (None, "", [], {}):
        normalized = _normalize_framework_capability_key(expected_framework)
        _append_framework_capability_check(
            checks,
            findings,
            check="framework",
            expected=normalized,
            actual=observed["frameworks"],
            match=normalized in observed["frameworks"],
            finding_type="framework_capability_framework_mismatch",
        )

    required_capabilities = _string_list(
        requirements.get("required_capabilities")
        or requirements.get("capabilities")
        or requirements.get("supported_capabilities")
    )
    for capability in required_capabilities:
        normalized = _normalize_framework_capability_key(capability)
        _append_framework_capability_check(
            checks,
            findings,
            check="required_capability",
            expected=normalized,
            actual=observed["supported_capabilities"],
            match=normalized in observed["supported_capabilities"],
            finding_type="framework_capability_required_capability_missing",
        )

    for category in _string_list(requirements.get("required_categories") or requirements.get("categories")):
        normalized = _normalize_framework_capability_category(category)
        _append_framework_capability_check(
            checks,
            findings,
            check="required_category",
            expected=normalized,
            actual=observed["supported_categories"],
            match=normalized in observed["supported_categories"],
            finding_type="framework_capability_category_missing",
        )

    for surface in _string_list(requirements.get("required_task_surfaces") or requirements.get("task_surfaces")):
        normalized = _normalize_framework_capability_key(surface)
        _append_framework_capability_check(
            checks,
            findings,
            check="required_task_surface",
            expected=normalized,
            actual=observed["task_surfaces"],
            match=normalized in observed["task_surfaces"],
            finding_type="framework_capability_task_surface_missing",
        )

    min_supported = _as_int(
        requirements.get("min_supported_capabilities")
        or requirements.get("min_supported_count")
    )
    if min_supported is not None:
        _append_framework_capability_check(
            checks,
            findings,
            check="min_supported_capabilities",
            expected=min_supported,
            actual=observed["supported_count"],
            match=observed["supported_count"] >= min_supported,
            finding_type="framework_capability_supported_count_low",
        )

    min_support_rate = _as_float(requirements.get("min_support_rate"))
    if min_support_rate is not None:
        _append_framework_capability_check(
            checks,
            findings,
            check="min_support_rate",
            expected=min_support_rate,
            actual=observed["support_rate"],
            match=observed["support_rate"] >= min_support_rate,
            finding_type="framework_capability_support_rate_low",
        )

    if requirements.get("require_evidence") is not None:
        required = bool(requirements.get("require_evidence"))
        _append_framework_capability_check(
            checks,
            findings,
            check="require_evidence",
            expected=required,
            actual=observed["evidence_count"] > 0,
            match=(observed["evidence_count"] > 0) is required,
            finding_type="framework_capability_evidence_missing",
        )

    max_missing = _as_int(requirements.get("max_missing_capabilities"))
    if max_missing is None:
        max_missing = _as_int(requirements.get("max_missing_count"))
    if max_missing is not None:
        _append_framework_capability_check(
            checks,
            findings,
            check="max_missing_capabilities",
            expected=max_missing,
            actual=observed["missing_count"],
            match=observed["missing_count"] <= max_missing,
            finding_type="framework_capability_missing_count_high",
        )

    forbidden_missing = [
        _normalize_framework_capability_key(capability)
        for capability in _string_list(requirements.get("forbidden_missing_capabilities"))
        if _normalize_framework_capability_key(capability)
    ]
    for capability in forbidden_missing:
        actual_missing = sorted(set(observed["missing_capabilities"]) | set(observed["blocked_capabilities"]))
        _append_framework_capability_check(
            checks,
            findings,
            check="forbidden_missing_capability",
            expected=capability,
            actual=actual_missing,
            match=capability not in actual_missing,
            finding_type="framework_capability_forbidden_missing",
        )

    bool_checks = (
        ("require_tools", "has_tools", "framework_capability_tools_missing"),
        ("require_memory", "has_memory", "framework_capability_memory_missing"),
        ("require_streaming", "has_streaming", "framework_capability_streaming_missing"),
        ("require_lifecycle", "has_lifecycle", "framework_capability_lifecycle_missing"),
        ("require_orchestration", "has_orchestration", "framework_capability_orchestration_missing"),
        ("require_security", "has_security", "framework_capability_security_missing"),
        ("require_observability", "has_observability", "framework_capability_observability_missing"),
        ("require_exports", "has_exports", "framework_capability_exports_missing"),
    )
    for key, observed_key, finding_type in bool_checks:
        if requirements.get(key) is None:
            continue
        required = bool(requirements.get(key))
        _append_framework_capability_check(
            checks,
            findings,
            check=key,
            expected=required,
            actual=observed[observed_key],
            match=observed[observed_key] is required,
            finding_type=finding_type,
        )

    for integration in _string_list(requirements.get("required_integrations") or requirements.get("integrations")):
        normalized = _normalize_framework_capability_key(integration)
        _append_framework_capability_check(
            checks,
            findings,
            check="required_integration",
            expected=normalized,
            actual=observed["integrations"],
            match=normalized in observed["integrations"],
            finding_type="framework_capability_integration_missing",
        )

    if not checks:
        return AgentReportMetricResult(
            name="framework_capability_quality",
            score=1.0,
            reason="No framework capability quality checks were configured.",
        )

    matched = sum(1 for check in checks if check["match"])
    return AgentReportMetricResult(
        name="framework_capability_quality",
        score=round(matched / len(checks), 4),
        reason=f"{matched}/{len(checks)} framework capability quality check(s) matched.",
        details={
            "checks": checks,
            "findings": findings,
            "observed": observed,
        },
    )


