def _agent_memory_lineage_payloads_from_context(context: Mapping[str, Any]) -> List[Dict[str, Any]]:
    payloads: List[Dict[str, Any]] = []
    final_state = _extract_final_state(context)
    state_payload = _as_dict(final_state.get("agent_memory_lineage"))
    if state_payload:
        payloads.append(state_payload)
    metadata_state = _as_dict(_as_dict(context.get("metadata", {})).get("environment_state"))
    metadata_payload = _as_dict(metadata_state.get("agent_memory_lineage"))
    if metadata_payload:
        payloads.append(metadata_payload)
    for artifact in _as_list(context.get("artifacts", [])):
        if str(_get(artifact, "type", "") or "").lower() != "trace":
            continue
        data = _as_dict(_get(artifact, "data", {}))
        metadata = _as_dict(_get(artifact, "metadata", {}))
        if _looks_like_agent_memory_lineage(data, metadata):
            payloads.append(data)
    for event in _as_list(context.get("events", [])):
        event_type = str(_get(event, "type", "") or "").lower()
        payload = _as_dict(_get(event, "payload", {}))
        metadata = _as_dict(_get(event, "metadata", {}))
        if _looks_like_agent_memory_lineage(payload, metadata):
            payloads.append(payload)
        elif "agent_memory_lineage" in event_type:
            payloads.append({"kind": "agent_memory_lineage", "events": [_as_dict(event)]})
    deduped: List[Dict[str, Any]] = []
    seen: set[str] = set()
    for payload in payloads:
        key = json.dumps(payload, sort_keys=True, default=str)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(payload)
    return deduped


def _agent_memory_lineage_observed(context: Mapping[str, Any]) -> set[str]:
    observed: set[str] = set()
    for payload in _agent_memory_lineage_payloads_from_context(context):
        observed.update({"agent_memory_lineage", "memory_lineage", "memory_provenance", "memory", "provenance"})
        for signal in _as_list(payload.get("signals", [])):
            normalized = _normalize_agent_memory_lineage_key(signal)
            if normalized:
                observed.add(normalized)
        summary = _as_dict(payload.get("summary"))
        for key in ("observed_evidence", "observed_signals", "operation_types", "policy_keys"):
            observed.update(
                _normalize_agent_memory_lineage_key(item)
                for item in _as_list(summary.get(key))
                if _normalize_agent_memory_lineage_key(item)
            )
        for summary_key, signal in [
            ("has_target", "target"),
            ("has_stores", "store"),
            ("has_memory_records", "memory_record"),
            ("has_operations", "operation"),
            ("has_lineage", "lineage"),
            ("has_source_attribution", "source_attribution"),
            ("has_tenant_isolation", "tenant_isolation"),
            ("has_audit", "audit"),
            ("has_retention_policy", "retention_policy"),
            ("has_deletion_policy", "deletion_policy"),
            ("has_redaction", "redaction"),
            ("has_canaries", "canary"),
            ("has_observability", "observability"),
            ("has_artifacts", "artifact"),
        ]:
            if summary.get(summary_key):
                observed.add(signal)
        for operation_type in _as_list(summary.get("operation_types")):
            normalized = _agent_memory_lineage_operation(operation_type)
            if normalized:
                observed.update({normalized, f"{normalized}_operation"})
        for policy_key in _as_list(summary.get("policy_keys")):
            normalized = _normalize_agent_memory_lineage_key(policy_key)
            if normalized:
                observed.add(normalized)
        for key, marker in [
            ("target", "target"),
            ("stores", "store"),
            ("memories", "memory_record"),
            ("operations", "operation"),
            ("lineage", "lineage"),
            ("poison_tests", "poison_test"),
            ("isolation_tests", "isolation_test"),
            ("retention_tests", "retention_test"),
            ("artifacts", "artifact"),
        ]:
            if _as_list(payload.get(key)):
                observed.add(marker)
        if _as_dict(payload.get("observability")):
            observed.add("observability")
        policies = _as_dict(payload.get("policies"))
        for policy_key in policies.keys():
            normalized = _normalize_agent_memory_lineage_key(policy_key)
            if normalized:
                observed.add(normalized)
            if normalized in {"retention", "ttl", "expiry", "expiration", "retention_policy"}:
                observed.add("retention_policy")
            if normalized in {"deletion", "right_to_delete", "purge", "deletion_policy"}:
                observed.add("deletion_policy")
            if normalized in {"canaries", "canary_filter", "poisoning_canaries"}:
                observed.add("canary")
        for operation in _as_list(payload.get("operations")):
            operation_dict = _as_dict(operation)
            operation_type = _agent_memory_lineage_operation(
                operation_dict.get("operation") or operation_dict.get("type") or operation_dict.get("op")
            )
            if operation_type:
                observed.update({"operation", operation_type, f"{operation_type}_operation"})
            for signal in _as_list(operation_dict.get("signals")):
                normalized = _normalize_agent_memory_lineage_key(signal)
                if normalized:
                    observed.add(normalized)
        for section in (
            "stores",
            "memories",
            "lineage",
            "poison_tests",
            "isolation_tests",
            "retention_tests",
            "artifacts",
        ):
            for record in _as_list(payload.get(section)):
                for signal in _as_list(_as_dict(record).get("signals")):
                    normalized = _normalize_agent_memory_lineage_key(signal)
                    if normalized:
                        observed.add(normalized)
    for tool_call in _as_list(context.get("tool_calls", [])):
        name = str(_get(tool_call, "name", _get(tool_call, "tool", "")) or "").lower()
        if name in {
            "agent_memory_lineage_status",
            "list_memory_lineage_operations",
            "inspect_memory_lineage_record",
            "list_memory_lineage_gaps",
        }:
            observed.add("agent_memory_lineage")
            if "operations" in name:
                observed.add("operation")
            if "record" in name:
                observed.add("memory_record")
            if "gaps" in name:
                observed.add("gap")
    return {item for item in observed if item}


def _looks_like_agent_memory_lineage(data: Mapping[str, Any], metadata: Mapping[str, Any]) -> bool:
    kind = str(data.get("kind") or metadata.get("kind") or "").lower()
    return kind == "agent_memory_lineage" or (
        "memories" in data and ("operations" in data or "policies" in data or "poison_tests" in data)
    )


def _merge_agent_memory_lineage_summaries(payloads: Sequence[Mapping[str, Any]]) -> Dict[str, Any]:
    observed_evidence: set[str] = set()
    observed_signals: set[str] = set()
    operation_types: set[str] = set()
    policy_keys: set[str] = set()
    blocking_gaps: set[str] = set()
    missing_required_evidence: set[str] = set()
    missing_required_signals: set[str] = set()
    unattributed_memories: set[str] = set()
    poisoned_memories: set[str] = set()
    poisoning_failures: set[str] = set()
    isolation_violations: set[str] = set()
    retention_violations: set[str] = set()
    policy_violations: set[str] = set()
    summary: Dict[str, Any] = {
        "has_target": False,
        "has_stores": False,
        "has_memory_records": False,
        "has_operations": False,
        "has_lineage": False,
        "has_source_attribution": False,
        "has_tenant_isolation": False,
        "has_audit": False,
        "has_retention_policy": False,
        "has_deletion_policy": False,
        "has_redaction": False,
        "has_canaries": False,
        "has_observability": False,
        "has_artifacts": False,
        "store_count": 0,
        "memory_count": 0,
        "operation_count": 0,
        "read_operation_count": 0,
        "write_operation_count": 0,
        "update_operation_count": 0,
        "delete_operation_count": 0,
        "recall_operation_count": 0,
        "attributed_memory_count": 0,
        "unattributed_memory_count": 0,
        "poisoned_memory_count": 0,
        "open_poisoning_count": 0,
        "isolation_violation_count": 0,
        "retention_violation_count": 0,
        "policy_violation_count": 0,
        "audited_operation_count": 0,
        "artifact_count": 0,
        "observability_hook_count": 0,
    }
    for payload in payloads:
        payload_dict = _as_dict(payload)
        payload_summary = _as_dict(payload_dict.get("summary"))
        if payload_summary:
            for key in [
                "has_target",
                "has_stores",
                "has_memory_records",
                "has_operations",
                "has_lineage",
                "has_source_attribution",
                "has_tenant_isolation",
                "has_audit",
                "has_retention_policy",
                "has_deletion_policy",
                "has_redaction",
                "has_canaries",
                "has_observability",
                "has_artifacts",
            ]:
                summary[key] = summary[key] or bool(payload_summary.get(key))
            for key in [
                "store_count",
                "memory_count",
                "operation_count",
                "read_operation_count",
                "write_operation_count",
                "update_operation_count",
                "delete_operation_count",
                "recall_operation_count",
                "attributed_memory_count",
                "unattributed_memory_count",
                "poisoned_memory_count",
                "open_poisoning_count",
                "isolation_violation_count",
                "retention_violation_count",
                "policy_violation_count",
                "audited_operation_count",
                "artifact_count",
                "observability_hook_count",
            ]:
                summary[key] += _as_int(payload_summary.get(key)) or 0
            observed_evidence.update(
                _normalize_agent_memory_lineage_key(item)
                for item in _as_list(payload_summary.get("observed_evidence"))
                if _normalize_agent_memory_lineage_key(item)
            )
            observed_signals.update(
                _normalize_agent_memory_lineage_key(item)
                for item in _as_list(payload_summary.get("observed_signals"))
                if _normalize_agent_memory_lineage_key(item)
            )
            operation_types.update(
                _agent_memory_lineage_operation(item)
                for item in _as_list(payload_summary.get("operation_types"))
                if _agent_memory_lineage_operation(item)
            )
            policy_keys.update(
                _normalize_agent_memory_lineage_key(item)
                for item in _as_list(payload_summary.get("policy_keys"))
                if _normalize_agent_memory_lineage_key(item)
            )
            blocking_gaps.update(str(item) for item in _as_list(payload_summary.get("blocking_gaps")) if item)
            missing_required_evidence.update(
                _normalize_agent_memory_lineage_key(item)
                for item in _as_list(payload_summary.get("missing_required_evidence"))
                if _normalize_agent_memory_lineage_key(item)
            )
            missing_required_signals.update(
                _normalize_agent_memory_lineage_key(item)
                for item in _as_list(payload_summary.get("missing_required_signals"))
                if _normalize_agent_memory_lineage_key(item)
            )
            unattributed_memories.update(str(item) for item in _as_list(payload_summary.get("unattributed_memories")) if item)
            poisoned_memories.update(str(item) for item in _as_list(payload_summary.get("poisoned_memories")) if item)
            poisoning_failures.update(str(item) for item in _as_list(payload_summary.get("poisoning_failures")) if item)
            isolation_violations.update(str(item) for item in _as_list(payload_summary.get("isolation_violations")) if item)
            retention_violations.update(str(item) for item in _as_list(payload_summary.get("retention_violations")) if item)
            policy_violations.update(str(item) for item in _as_list(payload_summary.get("policy_violations")) if item)
            continue

        stores = [_as_dict(item) for item in _as_list(payload_dict.get("stores"))]
        memories = [_as_dict(item) for item in _as_list(payload_dict.get("memories"))]
        operations = [_as_dict(item) for item in _as_list(payload_dict.get("operations"))]
        policies = _as_dict(payload_dict.get("policies"))
        poison_tests = [
            _as_dict(item)
            for item in _as_list(payload_dict.get("poison_tests") or payload_dict.get("poisoning_tests"))
        ]
        isolation_tests = [_as_dict(item) for item in _as_list(payload_dict.get("isolation_tests"))]
        retention_tests = [
            _as_dict(item)
            for item in _as_list(payload_dict.get("retention_tests") or payload_dict.get("deletion_tests"))
        ]
        observability = _as_dict(payload_dict.get("observability"))
        artifacts = [_as_dict(item) for item in _as_list(payload_dict.get("artifacts"))]
        summary["has_target"] = summary["has_target"] or bool(_as_dict(payload_dict.get("target")))
        summary["has_stores"] = summary["has_stores"] or bool(stores)
        summary["has_memory_records"] = summary["has_memory_records"] or bool(memories)
        summary["has_operations"] = summary["has_operations"] or bool(operations)
        summary["has_lineage"] = summary["has_lineage"] or bool(_as_list(payload_dict.get("lineage")))
        summary["store_count"] += len(stores)
        summary["memory_count"] += len(memories)
        summary["operation_count"] += len(operations)
        for operation in operations:
            operation_type = _agent_memory_lineage_operation(operation.get("operation") or operation.get("type") or operation.get("op"))
            operation_types.add(operation_type)
            key = f"{operation_type}_operation_count"
            if key in summary:
                summary[key] += 1
            if operation.get("trace_id") or operation.get("audit_id") or operation.get("evidence"):
                summary["audited_operation_count"] += 1
            operation_status = _normalize_agent_memory_lineage_key(operation.get("status"))
            policy_decision = _normalize_agent_memory_lineage_key(operation.get("policy_decision"))
            if operation_status in {"policy_violation", "violation", "failed_policy"} or policy_decision in {
                "violation",
                "failed",
                "bypassed",
            }:
                policy_violations.add(str(operation.get("id") or operation.get("name") or len(policy_violations) + 1))
        source_backed = [item for item in memories if _as_list(item.get("source_ids") or item.get("sources") or item.get("doc_ids"))]
        summary["attributed_memory_count"] += len(source_backed)
        for index, memory in enumerate(memories, start=1):
            memory_id = str(memory.get("id") or memory.get("key") or index)
            status = _normalize_agent_memory_lineage_key(memory.get("status"))
            has_source = bool(_as_list(memory.get("source_ids") or memory.get("sources") or memory.get("doc_ids")))
            if not has_source and memory.get("requires_attribution", True) is not False and status not in {
                "deleted",
                "expired",
                "blocked",
            }:
                unattributed_memories.add(memory_id)
            if status in {"poisoned", "tainted", "untrusted", "compromised"}:
                poisoned_memories.add(memory_id)
        policy_keys.update(_normalize_agent_memory_lineage_key(item) for item in policies.keys() if _normalize_agent_memory_lineage_key(item))
        poison_good = {"passed", "blocked", "mitigated", "contained", "accepted"}
        for index, poison_test in enumerate(poison_tests, start=1):
            if _normalize_agent_memory_lineage_key(poison_test.get("status")) not in poison_good:
                poisoning_failures.add(str(poison_test.get("id") or poison_test.get("name") or index))
        isolation_good = {"passed", "blocked", "mitigated", "contained"}
        for index, isolation_test in enumerate(isolation_tests, start=1):
            if _normalize_agent_memory_lineage_key(isolation_test.get("status")) not in isolation_good:
                isolation_violations.add(str(isolation_test.get("id") or isolation_test.get("name") or index))
        retention_good = {"passed", "deleted", "expired", "purged", "mitigated"}
        for index, retention_test in enumerate(retention_tests, start=1):
            if _normalize_agent_memory_lineage_key(retention_test.get("status")) not in retention_good:
                retention_violations.add(str(retention_test.get("id") or retention_test.get("name") or index))

        summary["artifact_count"] += len(artifacts)
        summary["observability_hook_count"] += _agent_memory_lineage_observability_count(observability)
        summary["has_artifacts"] = summary["has_artifacts"] or bool(artifacts)
        summary["has_observability"] = summary["has_observability"] or bool(observability)
        summary["has_source_attribution"] = summary["has_source_attribution"] or (bool(source_backed) and not unattributed_memories)
        summary["has_tenant_isolation"] = summary["has_tenant_isolation"] or bool(
            policy_keys & {"tenant_isolation", "memory_isolation", "namespace_isolation"}
        ) or any(_normalize_agent_memory_lineage_key(item.get("status")) in isolation_good for item in isolation_tests)
        summary["has_audit"] = summary["has_audit"] or bool(policy_keys & {"audit", "audit_log", "trace"}) or (
            bool(operations) and summary["audited_operation_count"] >= summary["operation_count"]
        )
        summary["has_retention_policy"] = summary["has_retention_policy"] or bool(
            policy_keys & {"retention_policy", "retention", "ttl", "expiry", "expiration"}
        )
        summary["has_deletion_policy"] = summary["has_deletion_policy"] or bool(
            policy_keys & {"deletion_policy", "deletion", "right_to_delete", "purge"}
        )
        summary["has_redaction"] = summary["has_redaction"] or bool(policy_keys & {"redaction", "pii_redaction", "secret_redaction"})
        summary["has_canaries"] = summary["has_canaries"] or bool(policy_keys & {"canaries", "canary_filter", "poisoning_canaries"}) or bool(poison_tests)
        if poison_tests:
            observed_evidence.add("poison_test")
        if isolation_tests:
            observed_evidence.add("isolation_test")
        if retention_tests:
            observed_evidence.add("retention_test")
        for operation_type in operation_types:
            observed_evidence.add(f"{operation_type}_operation")

    for key, evidence in [
        ("has_target", "target"),
        ("has_stores", "store"),
        ("has_memory_records", "memory_record"),
        ("has_operations", "operation"),
        ("has_lineage", "lineage"),
        ("has_source_attribution", "source_attribution"),
        ("has_tenant_isolation", "tenant_isolation"),
        ("has_audit", "audit"),
        ("has_retention_policy", "retention_policy"),
        ("has_deletion_policy", "deletion_policy"),
        ("has_redaction", "redaction"),
        ("has_canaries", "canary"),
        ("has_observability", "observability"),
        ("has_artifacts", "artifact"),
    ]:
        if summary[key]:
            observed_evidence.add(evidence)
    if unattributed_memories:
        blocking_gaps.add("source_attribution_missing")
    if poisoned_memories or poisoning_failures:
        blocking_gaps.add("poisoning_open")
    if isolation_violations:
        blocking_gaps.add("isolation_violation")
    if retention_violations:
        blocking_gaps.add("retention_or_deletion_violation")
    if policy_violations:
        blocking_gaps.add("policy_violation")
    observed_signals.update(observed_evidence)
    for operation_type in operation_types:
        observed_signals.update({operation_type, f"{operation_type}_operation"})
    observed_signals.update(policy_keys)
    observed_signals.update({"agent_memory_lineage", "memory_lineage", "memory_provenance", "memory", "provenance"})
    blocking_gaps.update(f"missing_evidence:{item}" for item in missing_required_evidence)
    blocking_gaps.update(f"missing_signal:{item}" for item in missing_required_signals)
    summary["unattributed_memories"] = sorted(item for item in unattributed_memories if item)
    summary["poisoned_memories"] = sorted(item for item in poisoned_memories if item)
    summary["poisoning_failures"] = sorted(item for item in poisoning_failures if item)
    summary["isolation_violations"] = sorted(item for item in isolation_violations if item)
    summary["retention_violations"] = sorted(item for item in retention_violations if item)
    summary["policy_violations"] = sorted(item for item in policy_violations if item)
    summary["unattributed_memory_count"] = max(
        summary["unattributed_memory_count"],
        len(summary["unattributed_memories"]),
    )
    summary["poisoned_memory_count"] = max(summary["poisoned_memory_count"], len(summary["poisoned_memories"]))
    summary["open_poisoning_count"] = max(
        summary["open_poisoning_count"],
        len(summary["poisoned_memories"]) + len(summary["poisoning_failures"]),
    )
    summary["isolation_violation_count"] = max(summary["isolation_violation_count"], len(summary["isolation_violations"]))
    summary["retention_violation_count"] = max(summary["retention_violation_count"], len(summary["retention_violations"]))
    summary["policy_violation_count"] = max(summary["policy_violation_count"], len(summary["policy_violations"]))
    summary["operation_types"] = sorted(item for item in operation_types if item)
    summary["policy_keys"] = sorted(item for item in policy_keys if item)
    summary["observed_evidence"] = sorted(item for item in observed_evidence if item)
    summary["observed_signals"] = sorted(item for item in observed_signals if item)
    summary["missing_required_evidence"] = sorted(item for item in missing_required_evidence if item)
    summary["missing_required_signals"] = sorted(item for item in missing_required_signals if item)
    summary["blocking_gaps"] = sorted(item for item in blocking_gaps if item)
    summary["blocking_gap_count"] = len(summary["blocking_gaps"])
    return summary


def _append_agent_memory_lineage_check(
    checks: List[Dict[str, Any]],
    findings: List[Dict[str, Any]],
    *,
    check: str,
    expected: Any,
    actual: Any,
    match: bool,
    finding_type: str,
) -> None:
    checks.append({"check": check, "expected": expected, "actual": actual, "match": match})
    if not match:
        findings.append(
            {
                "type": finding_type,
                "metric": "agent_memory_lineage_quality",
                "check": check,
                "expected": expected,
                "actual": actual,
            }
        )


def _agent_memory_lineage_operation(value: Any) -> str:
    normalized = _normalize_agent_memory_lineage_key(value)
    aliases = {
        "memory_write": "write",
        "write_memory": "write",
        "memory_read": "read",
        "retrieve_memory": "read",
        "memory_retrieval": "read",
        "memory_recall": "recall",
        "recall_memory": "recall",
        "forget": "delete",
        "purge": "delete",
        "erase": "delete",
        "sanitize": "update",
        "consolidate": "update",
    }
    return aliases.get(normalized, normalized)


def _normalize_agent_memory_lineage_key(value: Any) -> str:
    return str(value or "").strip().lower().replace("-", "_").replace(" ", "_").replace(".", "_")


def _agent_memory_lineage_observability_count(observability: Mapping[str, Any]) -> int:
    count = 0
    for value in observability.values():
        if isinstance(value, Mapping):
            count += len(value)
        elif isinstance(value, (list, tuple, set)):
            count += len([item for item in value if item])
        elif value:
            count += 1
    return count


def _retrieval_memory_attribution_metric(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> AgentReportMetricResult:
    required = [
        _normalize_retrieval_memory_key(key)
        for key in config.required_retrieval_memory_trace
    ]
    required = [key for key in required if key]
    if not required:
        return AgentReportMetricResult(
            name="retrieval_memory_attribution",
            score=1.0,
            reason="No required retrieval/memory trace keys provided.",
        )

    observed = _retrieval_memory_observed(context)
    missing = sorted(set(required) - observed)
    matched = len(set(required) - set(missing))
    score = matched / len(set(required)) if required else 1.0
    findings = [
        {"type": "missing_retrieval_memory_key", "key": key}
        for key in missing
    ]
    return AgentReportMetricResult(
        name="retrieval_memory_attribution",
        score=round(score, 4),
        reason=(
            "All required retrieval/memory attribution evidence observed."
            if not missing
            else f"Missing retrieval/memory attribution evidence: {', '.join(missing)}."
        ),
        details={
            "required": sorted(set(required)),
            "observed": sorted(observed),
            "missing": missing,
            "findings": findings,
        },
    )


def _retrieval_context_quality_metric(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> AgentReportMetricResult:
    expected = {str(doc_id) for doc_id in config.expected_retrieval_doc_ids}
    forbidden = {str(doc_id) for doc_id in config.forbidden_retrieval_doc_ids}
    if not expected and not forbidden and not config.require_current_retrieval:
        return AgentReportMetricResult(
            name="retrieval_context_quality",
            score=1.0,
            reason="No retrieval context quality requirements provided.",
        )

    traces = _retrieval_memory_traces(context)
    if not traces:
        return AgentReportMetricResult(
            name="retrieval_context_quality",
            score=0.0,
            reason="Retrieval context requirements provided, but no retrieval trace observed.",
            details={
                "expected_doc_ids": sorted(expected),
                "forbidden_doc_ids": sorted(forbidden),
                "require_current": config.require_current_retrieval,
                "findings": [{"type": "missing_retrieval_trace"}],
            },
        )

    docs_by_id = _retrieval_documents_by_id(traces)
    retrieved_sequences = _retrieval_query_sequences(traces, docs_by_id)
    retrieved_ids = _dedupe_preserve_order(
        doc_id
        for sequence in retrieved_sequences
        for doc_id in sequence
    )
    read_ids = _dedupe_preserve_order(_retrieval_document_read_ids(traces, docs_by_id))
    cited_ids = _dedupe_preserve_order(_retrieval_cited_doc_ids(traces))
    observed_ids = _dedupe_preserve_order([*retrieved_ids, *read_ids, *cited_ids])

    findings: List[Dict[str, Any]] = []
    components: Dict[str, float] = {}

    if expected:
        retrieved_expected = expected & set(retrieved_ids)
        missing_expected = sorted(expected - set(retrieved_ids))
        recall = len(retrieved_expected) / len(expected)
        precision = (
            len(retrieved_expected) / len(retrieved_ids)
            if retrieved_ids
            else 0.0
        )
        ranking_scores = []
        for doc_id in sorted(expected):
            try:
                rank = retrieved_ids.index(doc_id) + 1
                ranking_scores.append(1.0 / rank)
            except ValueError:
                ranking_scores.append(0.0)
        ranking = sum(ranking_scores) / len(ranking_scores)
        components.update(
            {
                "expected_recall": recall,
                "context_precision": precision,
                "ranking_mrr": ranking,
            }
        )
        findings.extend(
            {"type": "missing_expected_retrieval_document", "doc_id": doc_id}
            for doc_id in missing_expected
        )
        if retrieved_ids and precision < 1.0:
            findings.append(
                {
                    "type": "low_retrieval_precision",
                    "expected_doc_ids": sorted(expected),
                    "retrieved_doc_ids": retrieved_ids,
                    "precision": round(precision, 4),
                }
            )
        if ranking < 1.0:
            findings.append(
                {
                    "type": "retrieval_ranking_miss",
                    "expected_doc_ids": sorted(expected),
                    "retrieved_doc_ids": retrieved_ids,
                    "mrr": round(ranking, 4),
                }
            )

    if forbidden:
        forbidden_observed = sorted(forbidden & set(observed_ids))
        forbidden_score = 1.0 if not forbidden_observed else max(
            0.0,
            1.0 - (len(forbidden_observed) / len(forbidden)),
        )
        components["forbidden_context_absence"] = forbidden_score
        findings.extend(
            {"type": "forbidden_retrieval_document", "doc_id": doc_id}
            for doc_id in forbidden_observed
        )

    stale_doc_ids: List[str] = []
    if config.require_current_retrieval:
        for doc_id in observed_ids:
            document = docs_by_id.get(doc_id)
            if document is not None and document.get("current") is False:
                stale_doc_ids.append(doc_id)
        freshness = (
            1.0
            if not stale_doc_ids
            else max(0.0, 1.0 - (len(set(stale_doc_ids)) / max(1, len(set(observed_ids)))))
        )
        components["freshness"] = freshness
        findings.extend(
            {"type": "stale_retrieval_document", "doc_id": doc_id}
            for doc_id in sorted(set(stale_doc_ids))
        )

    score = sum(components.values()) / len(components) if components else 1.0
    return AgentReportMetricResult(
        name="retrieval_context_quality",
        score=round(score, 4),
        reason=(
            "Retrieved context matched expected relevance, ranking, and freshness."
            if not findings
            else f"{len(findings)} retrieval context issue(s)."
        ),
        details={
            "component_scores": {key: round(value, 4) for key, value in components.items()},
            "expected_doc_ids": sorted(expected),
            "forbidden_doc_ids": sorted(forbidden),
            "retrieved_doc_ids": retrieved_ids,
            "read_doc_ids": read_ids,
            "cited_doc_ids": cited_ids,
            "observed_doc_ids": observed_ids,
            "stale_doc_ids": sorted(set(stale_doc_ids)),
            "require_current": config.require_current_retrieval,
            "findings": findings,
        },
    )


def _source_grounding_metric(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> AgentReportMetricResult:
    if not config.require_source_grounding:
        return AgentReportMetricResult(
            name="source_grounding",
            score=1.0,
            reason="Source grounding not required.",
        )

    answer = _final_assistant_content(_as_list(context.get("messages", []))) or str(context.get("transcript") or "")
    answer_sentences = _answer_claim_sentences(answer)
    if not answer_sentences:
        return AgentReportMetricResult(
            name="source_grounding",
            score=0.0,
            reason="Source grounding required, but no final answer was observed.",
            details={"findings": [{"type": "missing_final_answer"}]},
        )

    traces = _retrieval_memory_traces(context)
    documents = _retrieval_documents_by_id(traces)
    source_ids = _grounding_source_doc_ids(traces, documents)
    source_text = " ".join(
        str(documents.get(doc_id, {}).get("content", ""))
        for doc_id in source_ids
    )
    if not source_text.strip():
        return AgentReportMetricResult(
            name="source_grounding",
            score=0.0,
            reason="Source grounding required, but no cited or retrieved source text was observed.",
            details={
                "answer": answer,
                "source_doc_ids": source_ids,
                "findings": [{"type": "missing_source_text"}],
            },
        )

    ignore_terms = {
        *SOURCE_GROUNDING_STOPWORDS,
        *{term.lower() for term in config.source_grounding_ignore_terms},
    }
    source_tokens = _grounding_tokens(source_text, ignore_terms)
    threshold = max(0.0, min(1.0, float(config.source_grounding_min_overlap)))
    claim_scores = []
    findings: List[Dict[str, Any]] = []

    for sentence in answer_sentences:
        claim_tokens = _grounding_tokens(sentence, ignore_terms)
        if not claim_tokens:
            continue
        overlap = claim_tokens & source_tokens
        score = len(overlap) / len(claim_tokens)
        record = {
            "claim": sentence,
            "score": round(score, 4),
            "matched_terms": sorted(overlap),
            "missing_terms": sorted(claim_tokens - source_tokens),
        }
        claim_scores.append(record)
        if score < threshold:
            findings.append({"type": "unsupported_claim", **record})

    if not claim_scores:
        return AgentReportMetricResult(
            name="source_grounding",
            score=0.0,
            reason="Source grounding required, but no checkable answer claims were observed.",
            details={
                "answer": answer,
                "source_doc_ids": source_ids,
                "findings": [{"type": "missing_checkable_claim"}],
            },
        )

    score = sum(item["score"] for item in claim_scores) / len(claim_scores)
    return AgentReportMetricResult(
        name="source_grounding",
        score=round(score, 4),
        reason=(
            "Final answer claims were supported by cited or retrieved source text."
            if not findings
            else f"{len(findings)} unsupported answer claim(s)."
        ),
        details={
            "answer": answer,
            "source_doc_ids": source_ids,
            "claim_scores": claim_scores,
            "threshold": threshold,
            "findings": findings,
        },
    )


def _source_contradiction_metrics(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> List[AgentReportMetricResult]:
    checks = _source_contradiction_checks(context, config)
    if not checks:
        return []
    return [_source_contradiction_metric(context, checks)]


def _source_contradiction_metric(
    context: Mapping[str, Any],
    checks: Sequence[Mapping[str, Any]],
) -> AgentReportMetricResult:
    answer = _trajectory_final_text(context)
    source_records = _source_evidence_records_from_context(context)
    source_text = "\n".join(record["text"] for record in source_records)
    normalized_checks: List[Dict[str, Any]] = []
    findings: List[Dict[str, Any]] = []

    for raw_check in checks:
        check = _normalize_source_contradiction_check(raw_check)
        if not check:
            continue
        source_terms = check["source_terms"]
        answer_terms = check["answer_terms"]
        contradict_terms = check["contradict_terms"]
        source_match = _terms_match(source_text, source_terms, require_all=check["require_all_source_terms"])
        answer_scope_match = not answer_terms or _terms_match(answer, answer_terms, require_all=False)
        matched_contradictions = [
            term for term in contradict_terms
            if _text_contains(answer, term) and answer_scope_match
        ]
        match = bool(source_match) and not matched_contradictions
        item = {
            "id": check["id"],
            "source_terms": source_terms,
            "answer_terms": answer_terms,
            "contradict_terms": contradict_terms,
            "source_match": bool(source_match),
            "answer_scope_match": bool(answer_scope_match),
            "matched_contradictions": matched_contradictions,
            "match": match,
        }
        normalized_checks.append(item)
        if not source_match:
            findings.append(
                {
                    "type": "missing_source_contradiction_evidence",
                    "id": check["id"],
                    "source_terms": source_terms,
                }
            )
        if matched_contradictions:
            findings.append(
                {
                    "type": "source_contradicted_claim",
                    "id": check["id"],
                    "answer_terms": answer_terms,
                    "contradict_terms": matched_contradictions,
                }
            )

    if not normalized_checks:
        return AgentReportMetricResult(
            name="source_contradiction",
            score=1.0,
            reason="No checkable source contradiction rules were configured.",
        )

    matched = sum(1 for check in normalized_checks if check["match"])
    score = matched / len(normalized_checks)
    return AgentReportMetricResult(
        name="source_contradiction",
        score=round(score, 4),
        reason=(
            "No source-supported answer contradictions observed."
            if not findings
            else f"{matched}/{len(normalized_checks)} source contradiction check(s) passed."
        ),
        details={
            "checks": normalized_checks,
            "source_records": source_records,
            "findings": findings,
        },
    )


def _browser_trace_coverage_metric(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> AgentReportMetricResult:
    required = [_normalize_browser_trace_key(key) for key in config.required_browser_trace]
    required = [key for key in required if key]
    if not required:
        return AgentReportMetricResult(
            name="browser_trace_coverage",
            score=1.0,
            reason="No required browser trace keys provided.",
        )

    observed = _browser_trace_observed(context)
    missing = sorted(set(required) - observed)
    matched = len(set(required) - set(missing))
    score = matched / len(set(required)) if required else 1.0
    findings = [
        {"type": "missing_browser_trace_key", "key": key}
        for key in missing
    ]
    return AgentReportMetricResult(
        name="browser_trace_coverage",
        score=round(score, 4),
        reason=(
            "All required browser trace evidence observed."
            if not missing
            else f"Missing browser trace evidence: {', '.join(missing)}."
        ),
        details={
            "required": sorted(set(required)),
            "observed": sorted(observed),
            "missing": missing,
            "findings": findings,
        },
    )


def _voice_turn_taking_metric(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> AgentReportMetricResult:
    findings: List[Dict[str, Any]] = []
    voice_events = [
        event
        for event in _as_list(context.get("events", []))
        if any(token in _stringify(event).lower() for token in ("voice", "vad", "stt", "tts", "barge", "interrupt"))
    ]
    for event in voice_events:
        text = _stringify(event).lower()
        if any(token in text for token in ("barge_in_failed", "missed_interrupt", "stt_error", "tts_error")):
            findings.append({"type": "voice_error", "event": text[:160]})
        latency = _extract_latency_ms(event)
        if latency is not None and config.max_voice_latency_ms is not None and latency > config.max_voice_latency_ms:
            findings.append({"type": "voice_latency", "latency_ms": latency})
    score = 1.0 if not findings else max(0.0, 1.0 - 0.25 * len(findings))
    return AgentReportMetricResult(
        name="voice_turn_taking",
        score=round(score, 4),
        reason="No voice turn-taking issues." if not findings else f"{len(findings)} voice issue(s).",
        details={"voice_events": len(voice_events), "findings": findings},
    )


def _voice_interaction_quality_metric(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> AgentReportMetricResult:
    if (
        not config.expected_voice_route
        and not config.expected_voice_transcript_contains
        and not config.required_voice_frame_types
        and config.max_voice_overlap_ms is None
        and config.max_voice_noise_db is None
        and not config.required_voice_speakers
        and config.min_voice_snr_db is None
        and config.min_voice_mos is None
        and config.max_voice_clipping_ratio is None
        and config.max_voice_jitter_ms is None
        and config.max_voice_packet_loss_pct is None
        and config.min_voice_sample_rate_hz is None
        and config.min_voice_duration_ms is None
        and config.max_voice_duration_ms is None
        and config.min_voice_rms_db is None
        and config.max_voice_peak_db is None
    ):
        return AgentReportMetricResult(
            name="voice_interaction_quality",
            score=1.0,
            reason="No expected voice interaction checks provided.",
        )

    payloads = _voice_trace_payloads_from_context(context)
    final_state = _extract_final_state(context)
    voice_state = _as_dict(final_state.get("voice"))
    checks: List[Dict[str, Any]] = []
    findings: List[Dict[str, Any]] = []

    if config.expected_voice_route:
        routes = _voice_routes_from_payloads(payloads, voice_state)
        match = str(config.expected_voice_route) in routes
        _append_voice_quality_check(
            checks,
            findings,
            check="route",
            expected=config.expected_voice_route,
            actual=routes,
            match=match,
            finding_type="voice_route_mismatch",
        )

    transcript_text = "\n".join(_voice_transcripts_from_payloads(payloads, context, voice_state))
    for expected in config.expected_voice_transcript_contains:
        phrase = str(expected)
        match = phrase.lower() in transcript_text.lower()
        _append_voice_quality_check(
            checks,
            findings,
            check="transcript_contains",
            expected=phrase,
            actual=match,
            match=match,
            finding_type="voice_transcript_missing",
        )

    observed_frames = _voice_frame_types_from_payloads(payloads, context, voice_state)
    for frame_type in config.required_voice_frame_types:
        expected = _normalize_voice_frame_type(frame_type)
        match = expected in observed_frames
        _append_voice_quality_check(
            checks,
            findings,
            check="frame_type",
            expected=str(frame_type),
            actual=sorted(observed_frames),
            match=match,
            finding_type="voice_frame_missing",
        )

    if config.max_voice_overlap_ms is not None:
        overlaps = _voice_overlap_values_from_payloads(payloads, context, voice_state)
        max_overlap = max(overlaps) if overlaps else 0
        match = max_overlap <= config.max_voice_overlap_ms
        _append_voice_quality_check(
            checks,
            findings,
            check="overlap_ms",
            expected=f"<= {config.max_voice_overlap_ms}",
            actual=max_overlap,
            match=match,
            finding_type="voice_overlap_exceeded",
        )

    if config.max_voice_noise_db is not None:
        noise_values = _voice_noise_values_from_payloads(payloads, context, voice_state)
        max_noise = max(noise_values) if noise_values else None
        match = max_noise is not None and max_noise <= config.max_voice_noise_db
        _append_voice_quality_check(
            checks,
            findings,
            check="noise_db",
            expected=f"<= {config.max_voice_noise_db}",
            actual=max_noise,
            match=match,
            finding_type="voice_noise_exceeded" if max_noise is not None else "voice_noise_missing",
        )

    if config.required_voice_speakers:
        observed_speakers = _voice_speakers_from_payloads(payloads, context, voice_state)
        normalized_observed = {speaker.lower() for speaker in observed_speakers}
        for speaker in config.required_voice_speakers:
            expected = str(speaker)
            match = expected.lower() in normalized_observed
            _append_voice_quality_check(
                checks,
                findings,
                check="speaker",
                expected=expected,
                actual=sorted(observed_speakers),
                match=match,
                finding_type="voice_speaker_missing",
            )

    if config.min_voice_snr_db is not None:
        values = _voice_quality_values_from_payloads(payloads, context, voice_state, "snr_db")
        min_snr = min(values) if values else None
        match = min_snr is not None and min_snr >= config.min_voice_snr_db
        _append_voice_quality_check(
            checks,
            findings,
            check="snr_db",
            expected=f">= {config.min_voice_snr_db}",
            actual=min_snr,
            match=match,
            finding_type="voice_snr_too_low" if min_snr is not None else "voice_snr_missing",
        )

    if config.min_voice_mos is not None:
        values = _voice_quality_values_from_payloads(payloads, context, voice_state, "mos")
        min_mos = min(values) if values else None
        match = min_mos is not None and min_mos >= config.min_voice_mos
        _append_voice_quality_check(
            checks,
            findings,
            check="mos",
            expected=f">= {config.min_voice_mos}",
            actual=min_mos,
            match=match,
            finding_type="voice_mos_too_low" if min_mos is not None else "voice_mos_missing",
        )

    if config.max_voice_clipping_ratio is not None:
        values = _voice_quality_values_from_payloads(payloads, context, voice_state, "clipping_ratio")
        max_clipping = max(values) if values else None
        match = max_clipping is not None and max_clipping <= config.max_voice_clipping_ratio
        _append_voice_quality_check(
            checks,
            findings,
            check="clipping_ratio",
            expected=f"<= {config.max_voice_clipping_ratio}",
            actual=max_clipping,
            match=match,
            finding_type="voice_clipping_exceeded" if max_clipping is not None else "voice_clipping_missing",
        )

    if config.max_voice_jitter_ms is not None:
        values = _voice_quality_values_from_payloads(payloads, context, voice_state, "jitter_ms")
        max_jitter = max(values) if values else None
        match = max_jitter is not None and max_jitter <= config.max_voice_jitter_ms
        _append_voice_quality_check(
            checks,
            findings,
            check="jitter_ms",
            expected=f"<= {config.max_voice_jitter_ms}",
            actual=max_jitter,
            match=match,
            finding_type="voice_jitter_exceeded" if max_jitter is not None else "voice_jitter_missing",
        )

    if config.max_voice_packet_loss_pct is not None:
        values = _voice_quality_values_from_payloads(payloads, context, voice_state, "packet_loss_pct")
        max_loss = max(values) if values else None
        match = max_loss is not None and max_loss <= config.max_voice_packet_loss_pct
        _append_voice_quality_check(
            checks,
            findings,
            check="packet_loss_pct",
            expected=f"<= {config.max_voice_packet_loss_pct}",
            actual=max_loss,
            match=match,
            finding_type="voice_packet_loss_exceeded" if max_loss is not None else "voice_packet_loss_missing",
        )

    if config.min_voice_sample_rate_hz is not None:
        values = _voice_quality_values_from_payloads(payloads, context, voice_state, "sample_rate_hz")
        min_rate = min(values) if values else None
        match = min_rate is not None and min_rate >= config.min_voice_sample_rate_hz
        _append_voice_quality_check(
            checks,
            findings,
            check="sample_rate_hz",
            expected=f">= {config.min_voice_sample_rate_hz}",
            actual=min_rate,
            match=match,
            finding_type="voice_sample_rate_too_low" if min_rate is not None else "voice_sample_rate_missing",
        )

    if config.min_voice_duration_ms is not None:
        values = _voice_quality_values_from_payloads(payloads, context, voice_state, "duration_ms")
        min_duration = min(values) if values else None
        match = min_duration is not None and min_duration >= config.min_voice_duration_ms
        _append_voice_quality_check(
            checks,
            findings,
            check="duration_ms_min",
            expected=f">= {config.min_voice_duration_ms}",
            actual=min_duration,
            match=match,
            finding_type="voice_duration_too_short" if min_duration is not None else "voice_duration_missing",
        )

    if config.max_voice_duration_ms is not None:
        values = _voice_quality_values_from_payloads(payloads, context, voice_state, "duration_ms")
        max_duration = max(values) if values else None
        match = max_duration is not None and max_duration <= config.max_voice_duration_ms
        _append_voice_quality_check(
            checks,
            findings,
            check="duration_ms_max",
            expected=f"<= {config.max_voice_duration_ms}",
            actual=max_duration,
            match=match,
            finding_type="voice_duration_too_long" if max_duration is not None else "voice_duration_missing",
        )

    if config.min_voice_rms_db is not None:
        values = _voice_quality_values_from_payloads(payloads, context, voice_state, "rms_db")
        min_rms = min(values) if values else None
        match = min_rms is not None and min_rms >= config.min_voice_rms_db
        _append_voice_quality_check(
            checks,
            findings,
            check="rms_db",
            expected=f">= {config.min_voice_rms_db}",
            actual=min_rms,
            match=match,
            finding_type="voice_rms_too_low" if min_rms is not None else "voice_rms_missing",
        )

    if config.max_voice_peak_db is not None:
        values = _voice_quality_values_from_payloads(payloads, context, voice_state, "peak_db")
        max_peak = max(values) if values else None
        match = max_peak is not None and max_peak <= config.max_voice_peak_db
        _append_voice_quality_check(
            checks,
            findings,
            check="peak_db",
            expected=f"<= {config.max_voice_peak_db}",
            actual=max_peak,
            match=match,
            finding_type="voice_peak_exceeded" if max_peak is not None else "voice_peak_missing",
        )

    if not checks:
        return AgentReportMetricResult(
            name="voice_interaction_quality",
            score=1.0,
            reason="No voice interaction quality checks were configured.",
        )

    matched = sum(1 for check in checks if check["match"])
    score = matched / len(checks)
    return AgentReportMetricResult(
        name="voice_interaction_quality",
        score=round(score, 4),
        reason=f"{matched}/{len(checks)} voice interaction check(s) matched.",
        details={"checks": checks, "findings": findings},
    )


def _voice_timing_distribution_quality_metric(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> AgentReportMetricResult:
    policy = _as_dict(config.voice_timing_distribution)
    if not policy:
        return AgentReportMetricResult(
            name="voice_timing_distribution_quality",
            score=1.0,
            reason="No voice timing distribution checks provided.",
        )

    distribution = _voice_timing_distribution_from_context(context)
    stages = _as_dict(distribution.get("stages", {}))
    stage_order = [
        stage
        for stage in (_normalize_voice_timing_stage_key(item) for item in _as_list(distribution.get("stage_order", [])))
        if stage
    ]
    checks: List[Dict[str, Any]] = []
    findings: List[Dict[str, Any]] = []

    def append_check(
        *,
        check: str,
        expected: Any,
        actual: Any,
        match: bool,
        finding_type: str,
        stage: Optional[str] = None,
    ) -> None:
        item = {
            "check": check,
            "expected": expected,
            "actual": actual,
            "match": bool(match),
        }
        if stage:
            item["stage"] = stage
        checks.append(item)
        if not match:
            findings.append({"type": finding_type, **item})

    append_check(
        check="distribution_present",
        expected=True,
        actual=bool(stages),
        match=bool(stages),
        finding_type="voice_timing_distribution_missing",
    )

    required_stages = [
        stage
        for stage in (_normalize_voice_timing_stage_key(item) for item in _as_list(policy.get("required_stages", [])))
        if stage
    ]
    for stage in required_stages:
        append_check(
            check="required_stage",
            stage=stage,
            expected=True,
            actual=stage in stages,
            match=stage in stages,
            finding_type="voice_timing_stage_missing",
        )

    min_samples = _as_int(policy.get("min_samples_per_stage", policy.get("min_stage_samples")))
    stage_min_samples = _voice_timing_budget_map(policy.get("min_samples_by_stage", policy.get("min_stage_samples_by_stage")))
    if min_samples is not None:
        stage_min_samples.update({stage: float(min_samples) for stage in (required_stages or stages.keys()) if stage not in stage_min_samples})
    for stage, minimum in stage_min_samples.items():
        sample_count = _as_int(_as_dict(stages.get(stage, {})).get("count")) or 0
        append_check(
            check="min_samples",
            stage=stage,
            expected=f">= {int(minimum)}",
            actual=sample_count,
            match=sample_count >= minimum,
            finding_type="voice_timing_sample_count_low" if stage in stages else "voice_timing_stage_missing",
        )

    for policy_key, stat_key, finding_type in (
        ("max_stage_p95_ms", "p95_ms", "voice_timing_p95_exceeded"),
        ("max_stage_max_ms", "max_ms", "voice_timing_max_exceeded"),
        ("max_stage_mean_ms", "mean_ms", "voice_timing_mean_exceeded"),
    ):
        for stage, budget in _voice_timing_budget_map(policy.get(policy_key)).items():
            actual = _as_float(_as_dict(stages.get(stage, {})).get(stat_key))
            append_check(
                check=policy_key,
                stage=stage,
                expected=f"<= {budget}",
                actual=actual,
                match=actual is not None and actual <= budget,
                finding_type=finding_type if actual is not None else "voice_timing_stage_missing",
            )

    for policy_key, stage, stat_key, finding_type in (
        ("max_turn_p95_ms", "turn", "p95_ms", "voice_timing_p95_exceeded"),
        ("max_total_p95_ms", "turn", "p95_ms", "voice_timing_p95_exceeded"),
        ("max_interruption_p95_ms", "interruption", "p95_ms", "voice_timing_p95_exceeded"),
        ("max_eou_p95_ms", "eou", "p95_ms", "voice_timing_p95_exceeded"),
    ):
        budget = _as_float(policy.get(policy_key))
        if budget is None:
            continue
        actual = _as_float(_as_dict(stages.get(stage, {})).get(stat_key))
        append_check(
            check=policy_key,
            stage=stage,
            expected=f"<= {budget}",
            actual=actual,
            match=actual is not None and actual <= budget,
            finding_type=finding_type if actual is not None else "voice_timing_stage_missing",
        )

    required_order = [
        stage
        for stage in (_normalize_voice_timing_stage_key(item) for item in _as_list(policy.get("required_order", [])))
        if stage
    ]
    if required_order:
        observed_order = [stage for stage in stage_order if stage in required_order]
        append_check(
            check="required_order",
            expected=required_order,
            actual=observed_order,
            match=observed_order == required_order,
            finding_type="voice_timing_order_mismatch",
        )

    matched = sum(1 for check in checks if check["match"])
    score = matched / len(checks) if checks else 1.0
    return AgentReportMetricResult(
        name="voice_timing_distribution_quality",
        score=round(score, 4),
        reason=f"{matched}/{len(checks)} voice timing distribution check(s) matched.",
        details={
            "distribution": distribution,
            "checks": checks,
            "findings": findings,
        },
    )


def _voice_timing_distribution_quality_metrics(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> List[AgentReportMetricResult]:
    if not config.voice_timing_distribution:
        return []
    return [_voice_timing_distribution_quality_metric(context, config)]


def _voice_trace_coverage_metric(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> AgentReportMetricResult:
    required = [_normalize_voice_trace_key(key) for key in config.required_voice_trace]
    required = [key for key in required if key]
    if not required:
        return AgentReportMetricResult(
            name="voice_trace_coverage",
            score=1.0,
            reason="No required voice trace keys provided.",
        )

    observed = _voice_trace_observed(context)
    missing = sorted(set(required) - observed)
    matched = len(set(required) - set(missing))
    score = matched / len(set(required)) if required else 1.0
    findings = [
        {"type": "missing_voice_trace_key", "key": key}
        for key in missing
    ]
    return AgentReportMetricResult(
        name="voice_trace_coverage",
        score=round(score, 4),
        reason=(
            "All required voice trace evidence observed."
            if not missing
            else f"Missing voice trace evidence: {', '.join(missing)}."
        ),
        details={
            "required": sorted(set(required)),
            "observed": sorted(observed),
            "missing": missing,
            "findings": findings,
        },
    )


def _evaluation_hook_metrics(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> List[AgentReportMetricResult]:
    hooks = [
        _as_dict(hook)
        for hook in _as_list(config.evaluation_hooks)
        if _as_dict(hook)
    ]
    if not hooks:
        return []

    results: List[AgentReportMetricResult] = []
    for index, hook in enumerate(hooks, start=1):
        hook_name = str(
            hook.get("metric_name")
            or hook.get("name")
            or f"external_evaluation_{index}"
        )
        started = time.time()
        status_code = 0
        response_payload: Any = {}
        error = ""
        try:
            status_code, response_payload = _post_evaluation_hook(
                hook,
                context=context,
                config=config,
            )
        except Exception as exc:
            error = str(exc)
            response_payload = {"error": str(exc)}

        if status_code >= 400 and not error:
            error = _evaluation_hook_error_text(response_payload) or (
                f"Evaluation hook returned status {status_code}"
            )
        latency_ms = round((time.time() - started) * 1000, 4)
        trace = _evaluation_hook_trace(
            hook,
            status_code=status_code,
            latency_ms=latency_ms,
            success=not error and 200 <= status_code < 300,
            error=error or None,
        )
        if error:
            results.append(
                AgentReportMetricResult(
                    name=hook_name,
                    score=0.0,
                    reason=f"Evaluation hook failed: {error}",
                    details={"evaluation_hook_trace": trace},
                )
            )
            continue
        results.extend(
            _evaluation_hook_results_from_payload(
                response_payload,
                hook_name=hook_name,
                trace=trace,
            )
        )
    return results


def _post_evaluation_hook(
    hook: Mapping[str, Any],
    *,
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> tuple[int, Any]:
    endpoint = str(hook.get("endpoint") or hook.get("url") or "")
    if not endpoint:
        raise ValueError("evaluation hook requires endpoint")
    payload = {
        "task": {
            "description": config.task_description,
            "expected_result": config.expected_result,
            "success_criteria": list(config.success_criteria),
        },
        "case": {
            "messages": _plain_json_value(_as_list(context.get("messages", []))),
            "tool_calls": _plain_json_value(_as_list(context.get("tool_calls", []))),
            "artifacts": _plain_json_value(_as_list(context.get("artifacts", []))),
            "events": _plain_json_value(_as_list(context.get("events", []))),
            "metadata": _plain_json_value(_as_dict(context.get("metadata", {}))),
        },
        "hook": {
            "name": hook.get("name") or hook.get("metric_name"),
            "metadata": _plain_json_value(_as_dict(hook.get("metadata", {}))),
        },
    }
    request = urllib.request.Request(
        endpoint,
        data=json.dumps(payload, default=str).encode("utf-8"),
        headers=_evaluation_hook_headers(hook),
        method=str(hook.get("method") or "POST").upper(),
    )
    timeout = float(hook.get("timeout") or 30.0)
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            status = int(getattr(response, "status", 200))
            text = response.read().decode(
                response.headers.get_content_charset() or "utf-8"
            )
    except urllib.error.HTTPError as exc:
        status = int(exc.code)
        text = exc.read().decode("utf-8")
    if not text:
        return status, {}
    try:
        return status, json.loads(text)
    except json.JSONDecodeError:
        return status, {"content": text, "score": 0.0}


def _evaluation_hook_results_from_payload(
    payload: Any,
    *,
    hook_name: str,
    trace: Mapping[str, Any],
) -> List[AgentReportMetricResult]:
    data = _as_dict(payload)
    raw_metrics = _as_list(data.get("metrics", []))
    if not raw_metrics:
        score_value = data.get("score", data.get("passed", data.get("pass")))
        raw_metrics = [
            {
                "name": data.get("metric_name") or data.get("name") or hook_name,
                "score": score_value,
                "reason": data.get("reason") or data.get("content") or "Evaluation hook completed.",
                "details": data.get("details") or data.get("summary") or {},
            }
        ]
    results: List[AgentReportMetricResult] = []
    for raw in raw_metrics:
        metric = _as_dict(raw)
        if not metric:
            continue
        name = str(metric.get("name") or metric.get("metric") or hook_name)
        details = _as_dict(metric.get("details"))
        details["evaluation_hook_trace"] = copy.deepcopy(dict(trace))
        if metric.get("summary") is not None:
            details.setdefault("summary", _plain_json_value(metric.get("summary")))
        results.append(
            AgentReportMetricResult(
                name=name,
                score=round(_score(metric.get("score", metric.get("passed"))), 4),
                reason=str(metric.get("reason") or "Evaluation hook completed."),
                details=details,
            )
        )
    return results or [
        AgentReportMetricResult(
            name=hook_name,
            score=0.0,
            reason="Evaluation hook returned no metrics.",
            details={"evaluation_hook_trace": copy.deepcopy(dict(trace))},
        )
    ]


def _evaluation_hook_headers(hook: Mapping[str, Any]) -> Dict[str, str]:
    headers = {
        "Content-Type": "application/json",
        **{str(k): str(v) for k, v in _as_dict(hook.get("headers")).items()},
    }
    for key, value in _evaluation_hook_auth_headers(_as_dict(hook.get("auth"))).items():
        headers.setdefault(key, value)
    return headers


def _evaluation_hook_auth_headers(auth: Mapping[str, Any]) -> Dict[str, str]:
    auth_map = _as_dict(auth)
    if not auth_map:
        return {}
    token = (
        auth_map.get("token")
        or auth_map.get("bearer_token")
        or auth_map.get("api_key")
    )
    token_env = (
        auth_map.get("token_env")
        or auth_map.get("api_key_env")
        or auth_map.get("env")
    )
    if not token and token_env:
        token = os.environ.get(str(token_env), "")
    auth_type = str(auth_map.get("type") or auth_map.get("scheme") or "").lower()
    if auth_type in {"bearer", "token"} and token:
        return {"Authorization": f"Bearer {token}"}
    if auth_type in {"api_key", "apikey"} and token:
        return {str(auth_map.get("header") or "X-API-Key"): str(token)}
    if auth_map.get("authorization"):
        return {"Authorization": str(auth_map["authorization"])}
    return {}


def _evaluation_hook_trace(
    hook: Mapping[str, Any],
    *,
    status_code: int,
    latency_ms: float,
    success: bool,
    error: Optional[str],
) -> Dict[str, Any]:
    endpoint = str(hook.get("endpoint") or hook.get("url") or "")
    headers = _evaluation_hook_headers(hook)
    auth = _as_dict(hook.get("auth"))
    auth_header_names = [
        name
        for name in sorted(headers)
        if name.lower()
        in {
            "authorization",
            "x-api-key",
            str(auth.get("header", "")).lower(),
        }
    ]
    return {
        "kind": "evaluation_hook_trace",
        "endpoint": _redacted_endpoint(endpoint),
        "endpoint_host": urlparse(endpoint).netloc,
        "method": str(hook.get("method") or "POST").upper(),
        "status_code": int(status_code),
        "latency_ms": latency_ms,
        "success": bool(success),
        "error": error,
        "request_header_names": sorted(headers),
        "auth": {
            "enabled": bool(auth or auth_header_names),
            "type": str(auth.get("type") or auth.get("scheme") or ""),
            "token_env": (
                auth.get("token_env")
                or auth.get("api_key_env")
                or auth.get("env")
            ),
            "header_names": sorted(set(auth_header_names)),
            "redacted": bool(auth or auth_header_names),
        },
        **copy.deepcopy(_as_dict(hook.get("metadata"))),
    }


def _redacted_endpoint(endpoint: str) -> str:
    parsed = urlparse(endpoint)
    if parsed.query:
        parsed = parsed._replace(query="<redacted>")
    return parsed.geturl()


def _evaluation_hook_error_text(payload: Any) -> str:
    data = _as_dict(payload)
    if data:
        error = data.get("error")
        if isinstance(error, Mapping):
            return str(error.get("message") or error.get("detail") or error)
        if error not in (None, ""):
            return str(error)
        for key in ("message", "detail", "content"):
            if data.get(key) not in (None, ""):
                return str(data.get(key))
    return "" if payload in (None, "") else str(payload)


def _plain_json_value(value: Any) -> Any:
    value = _dump_model(value)
    if isinstance(value, Mapping):
        return {str(key): _plain_json_value(val) for key, val in value.items()}
    if isinstance(value, list):
        return [_plain_json_value(item) for item in value]
    if isinstance(value, tuple):
        return [_plain_json_value(item) for item in value]
    return value


def _state_goal_metric(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> AgentReportMetricResult:
    if not config.expected_state:
        return AgentReportMetricResult(
            name="state_goal_accuracy",
            score=1.0,
            reason="No expected state provided.",
        )
    actual_state = _extract_final_state(context)
    if not actual_state:
        return AgentReportMetricResult(
            name="state_goal_accuracy",
            score=0.0,
            reason="Expected state provided, but no final state observed.",
            details={"expected_state": config.expected_state},
        )
    matches = {}
    for path, expected in _flatten_state(config.expected_state).items():
        actual = _get_path(actual_state, path)
        matches[path] = {"expected": expected, "actual": actual, "match": actual == expected}
    score = sum(1 for value in matches.values() if value["match"]) / len(matches)
    return AgentReportMetricResult(
        name="state_goal_accuracy",
        score=round(score, 4),
        reason=f"{sum(1 for value in matches.values() if value['match'])}/{len(matches)} expected state fields matched.",
        details={"matches": matches},
    )


def _artifact_coverage_metric(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> AgentReportMetricResult:
    required = [artifact_type.lower() for artifact_type in config.required_artifact_types]
    if not required:
        return AgentReportMetricResult(
            name="artifact_coverage",
            score=1.0,
            reason="No required artifact types provided.",
        )
    observed = {
        str(_get(artifact, "type", "") or "").lower()
        for artifact in _as_list(context.get("artifacts", []))
    }
    missing = sorted(set(required) - observed)
    matched = len(set(required) - set(missing))
    score = matched / len(set(required)) if required else 1.0
    return AgentReportMetricResult(
        name="artifact_coverage",
        score=round(score, 4),
        reason=(
            "All required artifact types observed."
            if not missing
            else f"Missing artifact types: {', '.join(missing)}."
        ),
        details={"required": required, "observed": sorted(observed), "missing": missing},
    )


def _artifact_grounding_metrics(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> List[AgentReportMetricResult]:
    checks = _artifact_grounding_checks(context, config)
    if not checks:
        return []
    return [_artifact_grounding_metric(context, checks)]


def _artifact_grounding_metric(
    context: Mapping[str, Any],
    checks: Sequence[Mapping[str, Any]],
) -> AgentReportMetricResult:
    answer = _trajectory_final_text(context)
    artifacts = _artifact_records_from_context(context)
    normalized_checks: List[Dict[str, Any]] = []
    findings: List[Dict[str, Any]] = []

    for raw_check in checks:
        check = _normalize_artifact_grounding_check(raw_check)
        if not check:
            continue
        matching_artifacts = [
            artifact for artifact in artifacts
            if _artifact_matches_expected(artifact, check["artifact"])
        ]
        artifact_text = "\n".join(_artifact_text(artifact) for artifact in matching_artifacts)
        answer_terms = check["answer_terms"]
        support_terms = check["support_terms"] or answer_terms
        forbidden_terms = check["forbidden_answer_terms"]
        claim_observed = _terms_match(answer, answer_terms, require_all=check["require_all_answer_terms"])
        artifact_support = bool(matching_artifacts) and _terms_match(
            artifact_text,
            support_terms,
            require_all=check["require_all_support_terms"],
        )
        forbidden_matches = [term for term in forbidden_terms if _text_contains(answer, term)]
        match = bool(claim_observed) and bool(artifact_support) and not forbidden_matches
        item = {
            "id": check["id"],
            "artifact": check["artifact"],
            "answer_terms": answer_terms,
            "support_terms": support_terms,
            "forbidden_answer_terms": forbidden_terms,
            "matching_artifact_count": len(matching_artifacts),
            "claim_observed": bool(claim_observed),
            "artifact_support": bool(artifact_support),
            "forbidden_matches": forbidden_matches,
            "match": match,
        }
        normalized_checks.append(item)
        if not matching_artifacts:
            findings.append(
                {
                    "type": "missing_grounding_artifact",
                    "id": check["id"],
                    "artifact": check["artifact"],
                }
            )
        elif not artifact_support:
            findings.append(
                {
                    "type": "artifact_support_missing",
                    "id": check["id"],
                    "support_terms": support_terms,
                }
            )
        if not claim_observed:
            findings.append(
                {
                    "type": "artifact_claim_missing",
                    "id": check["id"],
                    "answer_terms": answer_terms,
                }
            )
        if forbidden_matches:
            findings.append(
                {
                    "type": "artifact_contradicted_claim",
                    "id": check["id"],
                    "forbidden_answer_terms": forbidden_matches,
                }
            )

    if not normalized_checks:
        return AgentReportMetricResult(
            name="artifact_grounding_quality",
            score=1.0,
            reason="No checkable artifact grounding rules were configured.",
        )

    matched = sum(1 for check in normalized_checks if check["match"])
    score = matched / len(normalized_checks)
    return AgentReportMetricResult(
        name="artifact_grounding_quality",
        score=round(score, 4),
        reason=(
            "Answer claims matched artifact evidence."
            if not findings
            else f"{matched}/{len(normalized_checks)} artifact grounding check(s) passed."
        ),
        details={
            "checks": normalized_checks,
            "artifact_count": len(artifacts),
            "findings": findings,
        },
    )


def _artifact_semantic_metrics(
    context: Mapping[str, Any],
    config: AgentReportEvalConfig,
) -> List[AgentReportMetricResult]:
    checks = _artifact_semantic_checks(context, config)
    if not checks:
        return []
    return [_artifact_semantic_metric(context, checks)]


def _artifact_semantic_metric(
    context: Mapping[str, Any],
    checks: Sequence[Mapping[str, Any]],
) -> AgentReportMetricResult:
    answer = _trajectory_final_text(context)
    artifacts = _artifact_records_from_context(context)
    normalized_checks: List[Dict[str, Any]] = []
    findings: List[Dict[str, Any]] = []
    subchecks: List[Dict[str, Any]] = []

    for raw_check in checks:
        check = _normalize_artifact_semantic_check(raw_check)
        if not check:
            continue
        matching_artifacts = [
            artifact for artifact in artifacts
            if _artifact_matches_expected(artifact, check["artifact"])
        ]
        check_record = {
            "id": check["id"],
            "artifact": check["artifact"],
            "matching_artifact_count": len(matching_artifacts),
            "subchecks": [],
        }
        normalized_checks.append(check_record)
        if not matching_artifacts:
            finding = {
                "type": "missing_semantic_artifact",
                "id": check["id"],
                "artifact": check["artifact"],
            }
            findings.append(finding)
            subcheck = {"check": "artifact", "id": check["id"], "match": False, "finding": finding}
            subchecks.append(subcheck)
            check_record["subchecks"].append(subcheck)
            continue

        artifact = matching_artifacts[0]
        data = _artifact_semantic_payload(artifact)
        for path, expected in _flatten_state(check["expected_fields"]).items():
            actual = _get_path(data, path)
            match = _semantic_values_equal(actual, expected)
            subcheck = {
                "check": "field",
                "id": check["id"],
                "path": path,
                "expected": expected,
                "actual": actual,
                "match": match,
            }
            subchecks.append(subcheck)
            check_record["subchecks"].append(subcheck)
            if not match:
                findings.append(
                    {
                        "type": "artifact_field_mismatch",
                        "id": check["id"],
                        "path": path,
                        "expected": expected,
                        "actual": actual,
                    }
                )

        for answer_field in _semantic_answer_field_terms(check["answer_fields"], data):
            terms = answer_field["terms"]
            match = bool(terms) and any(_text_contains(answer, term) for term in terms)
            subcheck = {
                "check": "answer_field",
                "id": check["id"],
                "path": answer_field["path"],
                "terms": terms,
                "match": match,
            }
            subchecks.append(subcheck)
            check_record["subchecks"].append(subcheck)
            if not match:
                findings.append(
                    {
                        "type": "artifact_answer_field_missing",
                        "id": check["id"],
                        "path": answer_field["path"],
                        "terms": terms,
                    }
                )

        for raw_row in check["required_rows"]:
            row_path = str(raw_row.get("path") or raw_row.get("table") or raw_row.get("rows_path") or "rows")
            where = _as_dict(raw_row.get("where") or raw_row.get("match") or raw_row.get("key"))
            expected_fields = _as_dict(raw_row.get("fields") or raw_row.get("expected"))
            rows = _semantic_rows(data, row_path)
            matching_rows = [row for row in rows if _semantic_row_matches(row, where)] if where else rows
            row_match = bool(matching_rows)
            subcheck = {
                "check": "row",
                "id": check["id"],
                "path": row_path,
                "where": where,
                "match": row_match,
            }
            subchecks.append(subcheck)
            check_record["subchecks"].append(subcheck)
            if not row_match:
                findings.append(
                    {
                        "type": "artifact_row_missing",
                        "id": check["id"],
                        "path": row_path,
                        "where": where,
                    }
                )
                continue
            row = matching_rows[0]
            for field_path, expected in _flatten_state(expected_fields).items():
                actual = _get_path(row, field_path)
                match = _semantic_values_equal(actual, expected)
                field_subcheck = {
                    "check": "row_field",
                    "id": check["id"],
                    "path": f"{row_path}.{field_path}",
                    "where": where,
                    "expected": expected,
                    "actual": actual,
                    "match": match,
                }
                subchecks.append(field_subcheck)
                check_record["subchecks"].append(field_subcheck)
                if not match:
                    findings.append(
                        {
                            "type": "artifact_row_field_mismatch",
                            "id": check["id"],
                            "path": f"{row_path}.{field_path}",
                            "where": where,
                            "expected": expected,
                            "actual": actual,
                        }
                    )

        if check["event_sequence"]:
            expected_sequence = [
                _normalize_framework_name(item)
                for item in _string_list(
                    check["event_sequence"].get("expected")
                    or check["event_sequence"].get("sequence")
                    or check["event_sequence"].get("events")
                )
            ]
            observed_sequence = _semantic_event_values(data, check["event_sequence"])
            match = _contains_subsequence(observed_sequence, expected_sequence) if expected_sequence else True
            subcheck = {
                "check": "event_sequence",
                "id": check["id"],
                "expected": expected_sequence,
                "observed": observed_sequence,
                "match": match,
            }
            subchecks.append(subcheck)
            check_record["subchecks"].append(subcheck)
            if not match:
                findings.append(
                    {
                        "type": "artifact_event_sequence_mismatch",
                        "id": check["id"],
                        "expected": expected_sequence,
                        "observed": observed_sequence,
                    }
                )

        forbidden_matches = [term for term in check["forbidden_answer_terms"] if _text_contains(answer, term)]
        if check["forbidden_answer_terms"]:
            match = not forbidden_matches
            subcheck = {
                "check": "forbidden_answer_terms",
                "id": check["id"],
                "terms": check["forbidden_answer_terms"],
                "matches": forbidden_matches,
                "match": match,
            }
            subchecks.append(subcheck)
            check_record["subchecks"].append(subcheck)
            if forbidden_matches:
                findings.append(
                    {
                        "type": "artifact_semantic_forbidden_answer",
                        "id": check["id"],
                        "forbidden_answer_terms": forbidden_matches,
                    }
                )

    if not normalized_checks or not subchecks:
        return AgentReportMetricResult(
            name="artifact_semantics_quality",
            score=1.0,
            reason="No checkable artifact semantic rules were configured.",
        )

    matched = sum(1 for check in subchecks if check["match"])
    score = matched / len(subchecks)
    return AgentReportMetricResult(
        name="artifact_semantics_quality",
        score=round(score, 4),
        reason=(
            "Artifact semantic checks matched structured evidence."
            if not findings
            else f"{matched}/{len(subchecks)} artifact semantic subcheck(s) matched."
        ),
        details={
            "checks": normalized_checks,
            "subchecks": subchecks,
            "artifact_count": len(artifacts),
            "findings": findings,
        },
    )


