def _realtime_trace_payloads_from_context(context: Mapping[str, Any]) -> List[Dict[str, Any]]:
    payloads: List[Dict[str, Any]] = []
    final_state = _extract_final_state(context)
    state_payload = _as_dict(final_state.get("realtime_trace"))
    if state_payload:
        payloads.append(state_payload)
    metadata_state = _as_dict(_as_dict(context.get("metadata", {})).get("environment_state"))
    metadata_payload = _as_dict(metadata_state.get("realtime_trace"))
    if metadata_payload:
        payloads.append(metadata_payload)
    for artifact in _as_list(context.get("artifacts", [])):
        artifact_dict = _as_dict(artifact)
        metadata = _as_dict(artifact_dict.get("metadata"))
        data = _as_dict(artifact_dict.get("data"))
        if str(metadata.get("kind") or data.get("kind") or "").lower() in {
            "realtime_trace",
            "framework_realtime_trace",
        }:
            payloads.append(data)
    for event in _as_list(context.get("events", [])):
        event_dict = _as_dict(event)
        event_type = str(event_dict.get("type") or "")
        event_name = str(event_dict.get("name") or "")
        metadata = _as_dict(event_dict.get("metadata"))
        payload = _as_dict(event_dict.get("payload"))
        if str(metadata.get("kind") or payload.get("kind") or "").lower() in {
            "realtime_trace",
            "framework_realtime_trace",
        }:
            payloads.append(payload)
        elif (
            _is_realtime_trace_event_type(event_type)
            or _is_realtime_trace_event_type(event_name)
        ):
            payloads.append(
                {
                    "kind": "framework_realtime_trace",
                    "events": [payload],
                    "summary": {"event_types": [event_type]},
                    "signals": [event_type, event_name],
                }
            )
    return [payload for payload in payloads if payload]


def _realtime_trace_observed(context: Mapping[str, Any]) -> set[str]:
    observed: set[str] = set()
    for payload in _realtime_trace_payloads_from_context(context):
        observed.add("trace")
        _merge_realtime_trace_payload(observed, payload)
    return observed


def _merge_realtime_trace_payload(observed: set[str], payload: Mapping[str, Any]) -> None:
    if not payload:
        return
    if str(payload.get("kind") or "").lower() in {
        "framework_realtime_trace",
        "realtime_trace",
    }:
        observed.add("trace")
    summary = _as_dict(payload.get("summary"))
    for signal in _as_list(payload.get("signals") or summary.get("signals")):
        _add_realtime_trace_key(observed, str(signal))
    for count_key, signal in {
        "frame_count": "frame",
        "event_count": "event",
        "tool_call_count": "tool_call",
        "tool_response_count": "tool_response",
        "transcript_count": "transcript",
        "audio_frame_count": "audio_frame",
        "lifecycle_event_count": "lifecycle",
        "interruption_count": "interruption",
        "error_count": "error",
        "completion_count": "completion",
    }.items():
        if (
            (_as_int(summary.get(count_key)) or 0) > 0
            or (_as_int(payload.get(count_key)) or 0) > 0
        ):
            observed.add(signal)
            if signal in {"tool_call", "tool_response"}:
                observed.add("tool")
    for key in ("frame_types", "event_types", "categories", "directions", "modalities"):
        for value in _as_list(payload.get(key) or summary.get(key)):
            if key == "frame_types":
                observed.add("frame_type")
            elif key == "event_types":
                observed.add("event_type")
            _add_realtime_trace_key(observed, str(value))
    for frame in _as_list(payload.get("frames")):
        observed.add("frame")
        _merge_realtime_trace_item(observed, _as_dict(frame), source="frame")
    for event in _as_list(payload.get("events")):
        observed.add("event")
        _merge_realtime_trace_item(observed, _as_dict(event), source="event")
    if _as_list(payload.get("transcripts")):
        observed.add("transcript")
    if _as_list(payload.get("tool_names")) or _as_list(summary.get("tool_names")):
        observed.add("tool")


def _merge_realtime_trace_item(
    observed: set[str],
    item: Mapping[str, Any],
    *,
    source: str,
) -> None:
    if not item:
        return
    observed.add(source)
    if item.get("item_type") or item.get("type") or item.get("event"):
        observed.add("frame_type" if source == "frame" else "event_type")
    for key in ("kind", "category", "direction", "modality", "item_type", "type", "event"):
        _add_realtime_trace_key(observed, str(item.get(key) or ""))
    for signal in _as_list(item.get("signals")):
        _add_realtime_trace_key(observed, str(signal))
    if item.get("tool_name"):
        observed.update({"tool", "tool_call"})
    if item.get("text") or item.get("transcript"):
        observed.add("transcript")
    if item.get("sample_rate") or item.get("sample_rate_hz"):
        observed.add("audio_frame")


def _realtime_trace_summary_from_payloads(payloads: Sequence[Mapping[str, Any]]) -> Dict[str, Any]:
    summary: Dict[str, Any] = {
        "frame_count": 0,
        "event_count": 0,
        "tool_call_count": 0,
        "tool_response_count": 0,
        "transcript_count": 0,
        "audio_frame_count": 0,
        "lifecycle_event_count": 0,
        "interruption_count": 0,
        "error_count": 0,
        "completion_count": 0,
        "tool_names": set(),
        "frame_types": set(),
        "event_types": set(),
        "categories": set(),
        "directions": set(),
        "modalities": set(),
        "signals": set(),
        "transcripts": [],
    }
    for payload in payloads:
        payload_summary = _as_dict(payload.get("summary"))
        for key in (
            "frame_count",
            "event_count",
            "tool_call_count",
            "tool_response_count",
            "transcript_count",
            "audio_frame_count",
            "lifecycle_event_count",
            "interruption_count",
            "error_count",
            "completion_count",
        ):
            summary[key] = max(
                int(summary[key]),
                int(_as_int(payload_summary.get(key)) or _as_int(payload.get(key)) or 0),
            )
        for target_key in (
            "tool_names",
            "frame_types",
            "event_types",
            "categories",
            "directions",
            "modalities",
            "signals",
        ):
            source_values = _as_list(payload.get(target_key) or payload_summary.get(target_key))
            for item in source_values:
                normalized = (
                    _normalize_realtime_trace_name(item)
                    if target_key in {"frame_types", "event_types", "tool_names"}
                    else _normalize_realtime_trace_key(item)
                )
                if normalized:
                    summary[target_key].add(normalized)
        for transcript in _as_list(payload.get("transcripts")):
            transcript_dict = _as_dict(transcript)
            text = str(transcript_dict.get("text") or transcript)
            if text:
                summary["transcripts"].append(text)
        for frame in _as_list(payload.get("frames")):
            _merge_realtime_trace_summary_item(summary, _as_dict(frame), source="frame")
        for event in _as_list(payload.get("events")):
            _merge_realtime_trace_summary_item(summary, _as_dict(event), source="event")
    for key in ("frame_count", "event_count"):
        item_key = "frames" if key == "frame_count" else "events"
        count = max(
            (len(_as_list(payload.get(item_key))) for payload in payloads),
            default=0,
        )
        if count:
            summary[key] = max(int(summary[key]), count)
    return summary


def _merge_realtime_trace_summary_item(
    summary: Dict[str, Any],
    item: Mapping[str, Any],
    *,
    source: str,
) -> None:
    if not item:
        return
    item_type = _normalize_realtime_trace_name(
        item.get("item_type") or item.get("type") or item.get("event")
    )
    if item_type:
        target = "frame_types" if source == "frame" else "event_types"
        summary[target].add(item_type)
        summary["signals"].add("frame_type" if source == "frame" else "event_type")
    for target_key, item_key in (
        ("categories", "category"),
        ("directions", "direction"),
        ("modalities", "modality"),
        ("signals", "kind"),
    ):
        normalized = _normalize_realtime_trace_key(item.get(item_key))
        if normalized:
            summary[target_key].add(normalized)
    for signal in _as_list(item.get("signals")):
        normalized = _normalize_realtime_trace_key(signal)
        if normalized:
            summary["signals"].add(normalized)
    tool_name = _normalize_realtime_trace_name(item.get("tool_name"))
    if tool_name:
        summary["tool_names"].add(tool_name)
    text = str(item.get("text") or item.get("transcript") or "")
    if text:
        summary["transcripts"].append(text)


def _normalize_realtime_trace_key(value: Any) -> str:
    normalized = _normalize_protocol_key(value)
    aliases = {
        "realtime": "trace",
        "realtime_trace": "trace",
        "framework_realtime_trace": "trace",
        "frame": "frame",
        "frames": "frame",
        "realtime_frame": "frame",
        "event": "event",
        "events": "event",
        "session_event": "event",
        "session_events": "event",
        "audio": "audio_frame",
        "audio_frame": "audio_frame",
        "realtime_audio_frame": "audio_frame",
        "transcript": "transcript",
        "transcription": "transcript",
        "realtime_transcript": "transcript",
        "tool": "tool",
        "tool_call": "tool_call",
        "realtime_tool_call": "tool_call",
        "tool_response": "tool_response",
        "tool_result": "tool_response",
        "realtime_tool_response": "tool_response",
        "lifecycle": "lifecycle",
        "realtime_lifecycle": "lifecycle",
        "completion": "completion",
        "complete": "completion",
        "completed": "completion",
        "realtime_completion": "completion",
        "error": "error",
        "realtime_error": "error",
        "interruption": "interruption",
        "interrupt": "interruption",
        "realtime_interruption": "interruption",
        "data": "data_frame",
        "data_frame": "data_frame",
        "control": "control_frame",
        "control_frame": "control_frame",
        "system": "system_frame",
        "system_frame": "system_frame",
        "direction": "direction",
        "inbound": "inbound",
        "outbound": "outbound",
        "voice": "voice",
        "video": "video",
        "trace": "trace",
    }
    return aliases.get(normalized, normalized)


def _normalize_realtime_trace_name(value: Any) -> str:
    return _normalize_protocol_key(value)


def _add_realtime_trace_key(observed: set[str], value: str) -> None:
    normalized = _normalize_realtime_trace_key(value)
    if normalized:
        observed.add(normalized)


def _is_realtime_trace_event_type(value: Any) -> bool:
    normalized = _normalize_protocol_key(value)
    return bool(normalized and normalized.startswith("realtime_"))


def _mcp_tool_session_payloads_from_context(context: Mapping[str, Any]) -> List[Dict[str, Any]]:
    payloads: List[Dict[str, Any]] = []
    final_state = _extract_final_state(context)
    state_payload = _as_dict(final_state.get("mcp_tool_session"))
    if state_payload:
        payloads.append(state_payload)
    metadata_state = _as_dict(_as_dict(context.get("metadata", {})).get("environment_state"))
    metadata_payload = _as_dict(metadata_state.get("mcp_tool_session"))
    if metadata_payload:
        payloads.append(metadata_payload)
    for artifact in _as_list(context.get("artifacts", [])):
        artifact_dict = _as_dict(artifact)
        metadata = _as_dict(artifact_dict.get("metadata"))
        data = _as_dict(artifact_dict.get("data"))
        if str(metadata.get("kind") or data.get("kind") or "").lower() == "mcp_tool_session":
            payloads.append(data)
    for event in _as_list(context.get("events", [])):
        event_dict = _as_dict(event)
        event_type = str(event_dict.get("type") or "")
        metadata = _as_dict(event_dict.get("metadata"))
        payload = _as_dict(event_dict.get("payload"))
        if str(metadata.get("kind") or payload.get("kind") or "").lower() == "mcp_tool_session":
            payloads.append(payload)
        elif _is_mcp_tool_session_event_type(event_type):
            payloads.append({"kind": "mcp_tool_session", "spans": [payload]})
    return [payload for payload in payloads if payload]


def _mcp_tool_session_observed(context: Mapping[str, Any]) -> set[str]:
    observed: set[str] = set()
    for payload in _mcp_tool_session_payloads_from_context(context):
        observed.add("trace")
        _merge_mcp_tool_session_payload(observed, payload)
    for event in _as_list(context.get("events", [])):
        event_dict = _as_dict(event)
        event_type = str(event_dict.get("type") or "")
        event_name = str(event_dict.get("name") or "")
        payload = _as_dict(event_dict.get("payload"))
        if _is_mcp_tool_session_event_type(event_type):
            _add_mcp_tool_session_key(observed, event_type)
        if _is_mcp_tool_session_event_type(event_name):
            _add_mcp_tool_session_key(observed, event_name)
        if (
            _is_mcp_tool_session_event_type(event_type)
            or _is_mcp_tool_session_event_type(event_name)
            or str(payload.get("kind") or "").lower() == "mcp_tool_session"
        ):
            _merge_mcp_tool_session_payload(observed, payload)
    for tool_call in _as_list(context.get("tool_calls", [])):
        call = _as_dict(tool_call)
        if str(call.get("type") or "").lower() == "mcp_tool_call":
            observed.update({"tool", "tool_call"})
        if call.get("name") or call.get("tool"):
            observed.add("tool")
    for tool_response in _as_list(context.get("tool_responses", [])):
        response = _as_dict(tool_response)
        observed.add("tool_error" if response.get("error") else "tool_result")
    return observed


def _merge_mcp_tool_session_payload(observed: set[str], payload: Mapping[str, Any]) -> None:
    if not payload:
        return
    if str(payload.get("kind") or "").lower() == "mcp_tool_session":
        observed.update({"trace", "session"})
    summary = _as_dict(payload.get("summary"))
    for signal in _as_list(payload.get("signals") or summary.get("signals")):
        _add_mcp_tool_session_key(observed, str(signal))
    for record_type in _as_list(summary.get("record_types")):
        _add_mcp_tool_session_key(observed, str(record_type))
    for count_key, signal in {
        "server_count": "server",
        "schema_count": "tool_schema",
        "resource_count": "resource",
        "call_count": "tool_call",
        "result_count": "tool_result",
        "error_count": "tool_error",
        "tool_response_count": "tool_result",
        "tool_count": "tool",
    }.items():
        if (_as_int(summary.get(count_key)) or 0) > 0 or (_as_int(payload.get(count_key)) or 0) > 0:
            observed.add(signal)
    if _as_list(payload.get("tool_calls")):
        observed.update({"tool", "tool_call"})
    if _as_list(payload.get("tool_responses")):
        observed.add("tool_result")
    if _as_list(summary.get("server_names")) or payload.get("server_name"):
        observed.add("server")
    if _as_list(summary.get("session_ids")) or payload.get("session_id"):
        observed.add("session")
    for span in _as_list(payload.get("spans")):
        span_dict = _as_dict(span)
        _add_mcp_tool_session_key(observed, str(span_dict.get("type") or ""))
        _add_mcp_tool_session_key(observed, str(span_dict.get("name") or ""))
        for signal in _as_list(span_dict.get("signals")):
            _add_mcp_tool_session_key(observed, str(signal))
        attributes = _as_dict(span_dict.get("attributes"))
        if attributes.get("mcp.tool.name") or span_dict.get("tool_name"):
            observed.add("tool")
        if attributes.get("mcp.server.name"):
            observed.add("server")
        if attributes.get("mcp.session.id"):
            observed.add("session")


def _mcp_tool_session_summary_from_payloads(payloads: Sequence[Mapping[str, Any]]) -> Dict[str, Any]:
    summary: Dict[str, Any] = {
        "server_count": 0,
        "schema_count": 0,
        "resource_count": 0,
        "call_count": 0,
        "result_count": 0,
        "error_count": 0,
        "tool_response_count": 0,
        "tool_names": set(),
        "server_names": set(),
        "session_ids": set(),
    }
    for payload in payloads:
        payload_summary = _as_dict(payload.get("summary"))
        for key in (
            "server_count",
            "schema_count",
            "resource_count",
            "call_count",
            "result_count",
            "error_count",
            "tool_response_count",
        ):
            summary[key] = max(
                int(summary[key]),
                int(_as_int(payload_summary.get(key)) or _as_int(payload.get(key)) or 0),
            )
        summary["tool_names"].update(
            _normalize_protocol_name(item)
            for item in _as_list(payload_summary.get("tool_names") or payload.get("tool_names"))
            if _normalize_protocol_name(item)
        )
        summary["server_names"].update(
            _normalize_protocol_name(item)
            for item in _as_list(payload_summary.get("server_names") or payload.get("server_names"))
            if _normalize_protocol_name(item)
        )
        if payload.get("server_name"):
            summary["server_names"].add(_normalize_protocol_name(payload.get("server_name")))
        summary["session_ids"].update(
            str(item)
            for item in _as_list(payload_summary.get("session_ids") or payload.get("session_ids"))
            if str(item)
        )
        if payload.get("session_id"):
            summary["session_ids"].add(str(payload.get("session_id")))
        for tool_call in _as_list(payload.get("tool_calls")):
            call = _as_dict(tool_call)
            name = _normalize_protocol_name(call.get("name") or call.get("tool"))
            if name:
                summary["tool_names"].add(name)
        for span in _as_list(payload.get("spans")):
            span_dict = _as_dict(span)
            attributes = _as_dict(span_dict.get("attributes"))
            tool_name = _normalize_protocol_name(
                span_dict.get("tool_name") or attributes.get("mcp.tool.name")
            )
            if tool_name:
                summary["tool_names"].add(tool_name)
            server_name = _normalize_protocol_name(attributes.get("mcp.server.name"))
            if server_name:
                summary["server_names"].add(server_name)
            if attributes.get("mcp.session.id"):
                summary["session_ids"].add(str(attributes.get("mcp.session.id")))
    return summary


def _normalize_mcp_tool_session_key(value: Any) -> str:
    normalized = _normalize_protocol_key(value)
    aliases = {
        "mcp": "trace",
        "mcp_tool_session": "trace",
        "tool_session": "trace",
        "session": "session",
        "session_id": "session",
        "mcp_session": "session",
        "server": "server",
        "mcp_server": "server",
        "tool": "tool",
        "tools": "tool",
        "schema": "tool_schema",
        "tool_schema": "tool_schema",
        "mcp_tool_schema": "tool_schema",
        "resource": "resource",
        "mcp_resource": "resource",
        "call": "tool_call",
        "tool_call": "tool_call",
        "mcp_tool_call": "tool_call",
        "result": "tool_result",
        "tool_result": "tool_result",
        "mcp_tool_result": "tool_result",
        "error": "tool_error",
        "tool_error": "tool_error",
        "mcp_tool_error": "tool_error",
        "response": "tool_result",
        "tool_response": "tool_result",
        "trace": "trace",
    }
    return aliases.get(normalized, normalized)


def _add_mcp_tool_session_key(observed: set[str], value: str) -> None:
    normalized = _normalize_mcp_tool_session_key(value)
    if normalized:
        observed.add(normalized)


def _is_mcp_tool_session_event_type(value: Any) -> bool:
    raw = str(value or "").strip().lower()
    normalized = _normalize_protocol_key(value)
    return bool(
        normalized
        and (
            "mcp" in normalized
            or raw
            in {
                "tools/list",
                "tools/call",
                "resources/list",
                "resources/read",
                "resources/subscribe",
                "resources/unsubscribe",
            }
            or raw.startswith("notifications/tools/")
            or raw.startswith("notifications/resources/")
        )
    )


def _a2a_protocol_payloads_from_context(context: Mapping[str, Any]) -> List[Dict[str, Any]]:
    payloads: List[Dict[str, Any]] = []
    final_state = _extract_final_state(context)
    state_payload = _as_dict(final_state.get("a2a_protocol_trace"))
    if state_payload:
        payloads.append(state_payload)
    metadata_state = _as_dict(_as_dict(context.get("metadata", {})).get("environment_state"))
    metadata_payload = _as_dict(metadata_state.get("a2a_protocol_trace"))
    if metadata_payload:
        payloads.append(metadata_payload)
    for artifact in _as_list(context.get("artifacts", [])):
        artifact_dict = _as_dict(artifact)
        metadata = _as_dict(artifact_dict.get("metadata"))
        data = _as_dict(artifact_dict.get("data"))
        if str(metadata.get("kind") or data.get("kind") or "").lower() in {
            "a2a_protocol_trace",
            "a2a_artifact",
        }:
            payloads.append(data)
    for event in _as_list(context.get("events", [])):
        event_dict = _as_dict(event)
        event_type = str(event_dict.get("type") or "")
        metadata = _as_dict(event_dict.get("metadata"))
        payload = _as_dict(event_dict.get("payload"))
        if str(metadata.get("kind") or payload.get("kind") or "").lower() == "a2a_protocol_trace":
            payloads.append(payload)
        elif _is_a2a_protocol_event_type(event_type):
            payloads.append(
                {
                    "kind": "a2a_protocol_trace",
                    "events": [payload],
                    "summary": {"event_types": [event_type]},
                }
            )
    return [payload for payload in payloads if payload]


def _a2a_protocol_observed(context: Mapping[str, Any]) -> set[str]:
    observed: set[str] = set()
    for payload in _a2a_protocol_payloads_from_context(context):
        observed.add("trace")
        _merge_a2a_protocol_payload(observed, payload)
    for event in _as_list(context.get("events", [])):
        event_dict = _as_dict(event)
        event_type = str(event_dict.get("type") or "")
        event_name = str(event_dict.get("name") or "")
        payload = _as_dict(event_dict.get("payload"))
        if _is_a2a_protocol_event_type(event_type):
            _add_a2a_protocol_key(observed, event_type)
        if _is_a2a_protocol_event_type(event_name):
            _add_a2a_protocol_key(observed, event_name)
        if (
            _is_a2a_protocol_event_type(event_type)
            or _is_a2a_protocol_event_type(event_name)
            or str(payload.get("kind") or "").lower() == "a2a_protocol_trace"
        ):
            _merge_a2a_protocol_payload(observed, payload)
    return observed


def _merge_a2a_protocol_payload(observed: set[str], payload: Mapping[str, Any]) -> None:
    if not payload:
        return
    if str(payload.get("kind") or "").lower() == "a2a_protocol_trace":
        observed.add("trace")
    summary = _as_dict(payload.get("summary"))
    for event_type in _as_list(summary.get("event_types")):
        _add_a2a_protocol_key(observed, str(event_type))
    for count_key, signal in {
        "agent_card_count": "agent_card",
        "skill_count": "skill",
        "message_count": "message",
        "task_count": "task",
        "artifact_count": "artifact",
        "protocol_event_count": "protocol_event",
        "part_count": "part",
        "text_part_count": "text_part",
        "data_part_count": "data_part",
        "file_part_count": "file_part",
        "status_update_count": "status_update",
        "artifact_update_count": "artifact_update",
        "terminal_task_count": "terminal_task",
        "input_required_count": "input_required",
        "error_count": "error",
    }.items():
        if (_as_int(summary.get(count_key)) or _as_int(payload.get(count_key)) or 0) > 0:
            observed.add(signal)
    for key, signal in (
        ("agent_cards", "agent_card"),
        ("skills", "skill"),
        ("messages", "message"),
        ("tasks", "task"),
        ("artifacts", "artifact"),
        ("events", "protocol_event"),
    ):
        if _as_list(payload.get(key)):
            observed.add(signal)
    for event in _as_list(payload.get("events")):
        event_dict = _as_dict(event)
        _add_a2a_protocol_key(observed, str(event_dict.get("type") or event_dict.get("method") or ""))
        if event_dict.get("state"):
            observed.add("state")
        if event_dict.get("task_id"):
            observed.add("task_id")
        if event_dict.get("context_id"):
            observed.add("context")
        if event_dict.get("error"):
            observed.add("error")
    for message in _as_list(payload.get("messages")):
        message_dict = _as_dict(message)
        if message_dict.get("role"):
            observed.add("role")
        if message_dict.get("context_id"):
            observed.add("context")
        if message_dict.get("task_id"):
            observed.add("task_id")
        for part in _as_list(message_dict.get("parts")):
            _add_a2a_protocol_key(observed, f"{_as_dict(part).get('kind')}_part")
    for task in _as_list(payload.get("tasks")):
        task_dict = _as_dict(task)
        if task_dict.get("state"):
            observed.add("state")
        if task_dict.get("id"):
            observed.add("task_id")
        if task_dict.get("context_id"):
            observed.add("context")


def _a2a_protocol_summary_from_payloads(payloads: Sequence[Mapping[str, Any]]) -> Dict[str, Any]:
    summary: Dict[str, Any] = {
        "agent_card_count": 0,
        "skill_count": 0,
        "message_count": 0,
        "task_count": 0,
        "artifact_count": 0,
        "status_update_count": 0,
        "artifact_update_count": 0,
        "terminal_task_count": 0,
        "error_count": 0,
        "agent_names": set(),
        "skill_names": set(),
        "roles": set(),
        "states": set(),
    }
    for payload in payloads:
        payload_summary = _as_dict(payload.get("summary"))
        for key in (
            "agent_card_count",
            "skill_count",
            "message_count",
            "task_count",
            "artifact_count",
            "status_update_count",
            "artifact_update_count",
            "terminal_task_count",
            "error_count",
        ):
            summary[key] = max(
                int(summary[key]),
                int(_as_int(payload_summary.get(key)) or _as_int(payload.get(key)) or 0),
            )
        for target_key, payload_key in (
            ("agent_names", "agent_names"),
            ("skill_names", "skill_names"),
            ("roles", "roles"),
            ("states", "states"),
        ):
            summary[target_key].update(
                _normalize_protocol_name(item)
                for item in _as_list(payload_summary.get(payload_key) or payload.get(payload_key))
                if _normalize_protocol_name(item)
            )
        for card in _as_list(payload.get("agent_cards")):
            card_dict = _as_dict(card)
            name = _normalize_protocol_name(card_dict.get("name"))
            if name:
                summary["agent_names"].add(name)
            for skill in _as_list(card_dict.get("skills")):
                skill_dict = _as_dict(skill)
                skill_name = _normalize_protocol_name(skill_dict.get("name") or skill_dict.get("id"))
                if skill_name:
                    summary["skill_names"].add(skill_name)
        for message in _as_list(payload.get("messages")):
            role = _normalize_protocol_name(_as_dict(message).get("role"))
            if role:
                summary["roles"].add(role)
        for task in _as_list(payload.get("tasks")):
            state = _normalize_protocol_name(_as_dict(task).get("state"))
            if state:
                summary["states"].add(state)
    return summary


def _normalize_a2a_protocol_key(value: Any) -> str:
    normalized = _normalize_protocol_key(value)
    aliases = {
        "a2a": "trace",
        "agent2agent": "trace",
        "a2a_protocol": "trace",
        "a2a_protocol_trace": "trace",
        "agent_card": "agent_card",
        "a2a_agent_card": "agent_card",
        "card": "agent_card",
        "skill": "skill",
        "skills": "skill",
        "message": "message",
        "a2a_message": "message",
        "sendmessage": "message",
        "message_send": "message",
        "a2a_message_send": "message",
        "task": "task",
        "a2a_task": "task",
        "status": "status_update",
        "task_status": "status_update",
        "a2a_task_status": "status_update",
        "taskstatusupdateevent": "status_update",
        "artifact": "artifact",
        "a2a_artifact": "artifact",
        "task_artifact": "artifact_update",
        "a2a_task_artifact": "artifact_update",
        "taskartifactupdateevent": "artifact_update",
        "protocol_event": "protocol_event",
        "a2a_protocol_event": "protocol_event",
        "part": "part",
        "text_part": "text_part",
        "data_part": "data_part",
        "file_part": "file_part",
        "terminal": "terminal_task",
        "terminal_task": "terminal_task",
        "input_required": "input_required",
        "input_required_count": "input_required",
        "role": "role",
        "state": "state",
        "context": "context",
        "context_id": "context",
        "task_id": "task_id",
        "error": "error",
        "trace": "trace",
    }
    return aliases.get(normalized, normalized)


def _add_a2a_protocol_key(observed: set[str], value: str) -> None:
    normalized = _normalize_a2a_protocol_key(value)
    if normalized:
        observed.add(normalized)


def _is_a2a_protocol_event_type(value: Any) -> bool:
    raw = str(value or "").strip().lower()
    normalized = _normalize_protocol_key(value)
    return bool(
        normalized
        and (
            "a2a" in normalized
            or "agent2agent" in normalized
            or normalized in {"taskstatusupdateevent", "taskartifactupdateevent"}
            or raw in {"message/send", "message/stream"}
            or raw.startswith("tasks/")
        )
    )


def _normalize_protocol_key(value: Any) -> str:
    return (
        str(value or "")
        .strip()
        .lower()
        .replace("-", "_")
        .replace("/", "_")
        .replace(".", "_")
        .replace(" ", "_")
    )


def _normalize_protocol_name(value: Any) -> str:
    return _normalize_protocol_key(value)


def _protocol_summary_details(summary: Mapping[str, Any]) -> Dict[str, Any]:
    return {
        key: sorted(value) if isinstance(value, set) else value
        for key, value in summary.items()
    }


def _append_protocol_quality_check(
    checks: List[Dict[str, Any]],
    findings: List[Dict[str, Any]],
    *,
    metric: str,
    check: str,
    expected: Any,
    actual: Any,
    match: bool,
    finding_type: str,
) -> None:
    checks.append(
        {
            "check": check,
            "expected": expected,
            "actual": actual,
            "match": match,
        }
    )
    if not match:
        findings.append(
            {
                "type": finding_type,
                "metric": metric,
                "check": check,
                "expected": expected,
                "actual": actual,
            }
        )


def _retrieval_memory_observed(context: Mapping[str, Any]) -> set[str]:
    observed: set[str] = set()
    for payload in _retrieval_memory_state_payloads_from_context(context):
        observed.update({"retrieval_memory", "trace"})
        _merge_retrieval_memory_payload(observed, payload)

    for artifact in _as_list(context.get("artifacts", [])):
        artifact_type = str(_get(artifact, "type", "") or "").lower()
        if artifact_type != "trace":
            continue
        data = _as_dict(_get(artifact, "data", {}))
        metadata = _as_dict(_get(artifact, "metadata", {}))
        if _looks_like_retrieval_memory_trace(data, metadata):
            observed.add("trace")
            _merge_retrieval_memory_payload(observed, data)

    for event in _as_list(context.get("events", [])):
        event_type = str(_get(event, "type", "") or "").lower()
        name = str(_get(event, "name", "") or "").lower()
        payload = _as_dict(_get(event, "payload", {}))
        if any(token in event_type for token in ("retrieval", "memory", "citation", "attribution")):
            _add_retrieval_memory_key(observed, name)
            _merge_retrieval_memory_payload(observed, payload)

    for tool_call in _as_list(context.get("tool_calls", [])):
        name = str(_get(tool_call, "name", _get(tool_call, "tool", "")) or "").lower()
        _add_retrieval_memory_key(observed, name)
    return observed


def _retrieval_memory_traces(context: Mapping[str, Any]) -> List[Dict[str, Any]]:
    traces: List[Dict[str, Any]] = _retrieval_memory_state_payloads_from_context(context)
    for artifact in _as_list(context.get("artifacts", [])):
        artifact_type = str(_get(artifact, "type", "") or "").lower()
        if artifact_type != "trace":
            continue
        data = _as_dict(_get(artifact, "data", {}))
        metadata = _as_dict(_get(artifact, "metadata", {}))
        if _looks_like_retrieval_memory_trace(data, metadata):
            traces.append(data)
    return traces


def _retrieval_memory_state_payloads_from_context(context: Mapping[str, Any]) -> List[Dict[str, Any]]:
    payloads: List[Dict[str, Any]] = []
    final_state = _extract_final_state(context)
    state_payload = _as_dict(final_state.get("retrieval_memory"))
    if state_payload:
        payloads.append(state_payload)
    metadata_state = _as_dict(_as_dict(context.get("metadata", {})).get("environment_state"))
    metadata_payload = _as_dict(metadata_state.get("retrieval_memory"))
    if metadata_payload:
        payloads.append(metadata_payload)
    deduped: List[Dict[str, Any]] = []
    seen: set[str] = set()
    for payload in payloads:
        key = json.dumps(payload, sort_keys=True, default=str)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(payload)
    return deduped


def _retrieval_documents_by_id(
    traces: Sequence[Mapping[str, Any]],
) -> Dict[str, Dict[str, Any]]:
    documents: Dict[str, Dict[str, Any]] = {}
    for trace in traces:
        for raw_doc in _as_list(trace.get("documents", [])):
            doc = _as_dict(raw_doc)
            doc_id = _retrieval_doc_id(doc)
            if doc_id:
                documents[doc_id] = doc
        for raw_read in _as_list(trace.get("document_reads", [])):
            read = _as_dict(raw_read)
            doc = _as_dict(read.get("document", {}))
            doc_id = _retrieval_doc_id(doc) or str(read.get("id") or "")
            if doc_id and doc:
                documents[doc_id] = doc
    return documents


def _retrieval_query_sequences(
    traces: Sequence[Mapping[str, Any]],
    documents: Dict[str, Dict[str, Any]],
) -> List[List[str]]:
    sequences: List[List[str]] = []
    for trace in traces:
        for raw_query in _as_list(trace.get("queries", [])):
            query = _as_dict(raw_query)
            sequence: List[str] = []
            ranked_documents = _as_list(query.get("ranked_documents", []))
            if ranked_documents:
                ranked = []
                for index, raw_doc in enumerate(ranked_documents):
                    doc = _as_dict(raw_doc)
                    doc_id = _retrieval_doc_id(doc)
                    if not doc_id:
                        continue
                    rank = _as_int(doc.get("rank")) or index + 1
                    ranked.append((rank, doc_id))
                    if doc_id not in documents:
                        documents[doc_id] = doc
                ranked.sort(key=lambda item: item[0])
                sequence.extend(doc_id for _, doc_id in ranked)
            else:
                for raw_doc in _as_list(query.get("documents", [])):
                    if isinstance(raw_doc, Mapping):
                        doc = _as_dict(raw_doc)
                        doc_id = _retrieval_doc_id(doc)
                        if doc_id and doc_id not in documents:
                            documents[doc_id] = doc
                    else:
                        doc_id = str(raw_doc)
                    if doc_id:
                        sequence.append(doc_id)
            if sequence:
                sequences.append(sequence)
    return sequences


def _retrieval_document_read_ids(
    traces: Sequence[Mapping[str, Any]],
    documents: Dict[str, Dict[str, Any]],
) -> List[str]:
    ids: List[str] = []
    for trace in traces:
        for raw_read in _as_list(trace.get("document_reads", [])):
            read = _as_dict(raw_read)
            doc = _as_dict(read.get("document", {}))
            doc_id = str(read.get("id") or _retrieval_doc_id(doc) or "")
            if doc_id:
                ids.append(doc_id)
                if doc and doc_id not in documents:
                    documents[doc_id] = doc
    return ids


def _retrieval_cited_doc_ids(traces: Sequence[Mapping[str, Any]]) -> List[str]:
    ids: List[str] = []
    for trace in traces:
        for citation in _as_list(trace.get("citations", [])):
            payload = _as_dict(citation)
            ids.extend(str(doc_id) for doc_id in _as_list(payload.get("doc_ids", [])) if doc_id)
    return ids


def _grounding_source_doc_ids(
    traces: Sequence[Mapping[str, Any]],
    documents: Dict[str, Dict[str, Any]],
) -> List[str]:
    cited = _dedupe_preserve_order(_retrieval_cited_doc_ids(traces))
    if cited:
        return [doc_id for doc_id in cited if doc_id in documents]
    read = _dedupe_preserve_order(_retrieval_document_read_ids(traces, documents))
    if read:
        return [doc_id for doc_id in read if doc_id in documents]
    return _dedupe_preserve_order(
        doc_id
        for sequence in _retrieval_query_sequences(traces, documents)
        for doc_id in sequence
        if doc_id in documents
    )


def _answer_claim_sentences(answer: str) -> List[str]:
    return [
        sentence.strip(" \t\n\r-")
        for sentence in re.split(r"(?<=[.!?])\s+|\n+", str(answer))
        if sentence.strip(" \t\n\r-")
    ]


def _grounding_tokens(text: str, ignore_terms: set[str]) -> set[str]:
    tokens = set()
    for raw in re.findall(r"[A-Za-z0-9_]+", str(text).lower()):
        token = _normalize_grounding_token(raw)
        if len(token) < 2 or token in ignore_terms:
            continue
        tokens.add(token)
    return tokens


def _normalize_grounding_token(token: str) -> str:
    token = token.strip("_")
    for suffix in ("ing", "ed", "es", "s"):
        if len(token) > len(suffix) + 3 and token.endswith(suffix):
            token = token[: -len(suffix)]
            break
    if token.endswith("i"):
        token = f"{token[:-1]}y"
    return token


def _retrieval_doc_id(document: Mapping[str, Any]) -> str:
    return str(document.get("id") or document.get("doc_id") or document.get("source") or "")


def _dedupe_preserve_order(values: Iterable[Any]) -> List[str]:
    seen = set()
    deduped: List[str] = []
    for value in values:
        item = str(value)
        if not item or item in seen:
            continue
        seen.add(item)
        deduped.append(item)
    return deduped


def _as_int(value: Any) -> Optional[int]:
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return int(value)
    if isinstance(value, str):
        try:
            return int(value.strip())
        except ValueError:
            return None
    return None


def _as_float(value: Any) -> Optional[float]:
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value.strip())
        except ValueError:
            return None
    return None


def _looks_like_retrieval_memory_trace(data: Mapping[str, Any], metadata: Mapping[str, Any]) -> bool:
    kind = str(data.get("kind") or metadata.get("kind") or "").lower()
    return kind == "retrieval_memory_trace" or any(
        key in data for key in ("queries", "document_reads", "memory_reads", "memory_writes", "citations")
    )


def _merge_retrieval_memory_payload(observed: set[str], payload: Mapping[str, Any]) -> None:
    if _as_list(payload.get("queries", [])) or payload.get("query"):
        observed.add("query")
    if _as_list(payload.get("documents", [])) or payload.get("document"):
        observed.add("document")
    if _as_list(payload.get("document_reads", [])):
        observed.add("document")
    if _as_list(payload.get("memory_reads", [])):
        observed.add("memory_read")
    if _as_list(payload.get("memory_writes", [])):
        observed.add("memory_write")
    if _as_list(payload.get("citations", [])) or payload.get("citation"):
        observed.update({"citation", "attribution"})
    if payload.get("doc_ids") or payload.get("claim") or (
        payload.get("memory_keys") and (payload.get("doc_ids") or payload.get("claim"))
    ):
        observed.update({"citation", "attribution"})
    if payload.get("require_current") is not None:
        observed.add("freshness")
    for document in _as_list(payload.get("documents", [])):
        doc = _as_dict(document)
        if any(key in doc for key in ("version", "current", "last_modified", "status")):
            observed.add("freshness")
    for key, value in payload.items():
        if value is None or value is False:
            continue
        if isinstance(value, (list, tuple, set, dict)) and not value:
            continue
        _add_retrieval_memory_key(observed, str(key))


def _add_retrieval_memory_key(observed: set[str], value: str) -> None:
    key = _normalize_retrieval_memory_key(value)
    if key:
        observed.add(key)


def _normalize_retrieval_memory_key(key: str) -> str:
    normalized = str(key).strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "search_knowledge_base": "query",
        "query_knowledge": "query",
        "retrieve_documents": "query",
        "search": "query",
        "queries": "query",
        "retrieval_query": "query",
        "docs": "document",
        "documents": "document",
        "document_reads": "document",
        "read_document": "document",
        "context": "document",
        "contexts": "document",
        "retrieve_memory": "memory_read",
        "memory_reads": "memory_read",
        "memory_retrieval": "memory_read",
        "write_memory": "memory_write",
        "memory_writes": "memory_write",
        "memory_update": "memory_write",
        "cite_sources": "citation",
        "source": "citation",
        "sources": "citation",
        "source_document": "citation",
        "source_documents": "citation",
        "citations": "citation",
        "record_attribution": "attribution",
        "grounding": "attribution",
        "claim": "attribution",
        "version": "freshness",
        "current": "freshness",
        "last_modified": "freshness",
        "freshness_checked": "freshness",
        "retrieval_memory_status": "trace",
    }
    return aliases.get(normalized, normalized)


def _orchestration_trace_observed(context: Mapping[str, Any]) -> set[str]:
    observed: set[str] = set()
    for payload in _orchestration_trace_payloads_from_context(context):
        observed.add("trace")
        _merge_orchestration_trace_payload(observed, payload)

    for event in _as_list(context.get("events", [])):
        event_type = str(_get(event, "type", "") or "").lower()
        name = str(_get(event, "name", "") or "").lower()
        payload = _as_dict(_get(event, "payload", {}))
        if "orchestration" in event_type or "workflow" in event_type:
            observed.add("trace")
            _add_orchestration_trace_key(observed, event_type)
            _add_orchestration_trace_key(observed, name)
            _merge_orchestration_trace_payload(observed, payload)

    for tool_call in _as_list(context.get("tool_calls", [])):
        name = str(_get(tool_call, "name", _get(tool_call, "tool", "")) or "").lower()
        if name in {
            "orchestration_trace_status",
            "list_orchestration_steps",
            "inspect_orchestration_node",
            "inspect_orchestration_edge",
        }:
            observed.update({"trace", "step"})
        _add_orchestration_trace_key(observed, name)
    return observed


def _orchestration_trace_payloads_from_context(context: Mapping[str, Any]) -> List[Dict[str, Any]]:
    payloads: List[Dict[str, Any]] = []
    final_state = _extract_final_state(context)
    state_payload = _as_dict(final_state.get("orchestration_trace"))
    if state_payload:
        payloads.append(state_payload)
    replay_state = _as_dict(final_state.get("world_orchestration_replay"))
    replay_trace = _as_dict(replay_state.get("orchestration_trace"))
    if replay_trace:
        payloads.append(replay_trace)
    metadata_state = _as_dict(_as_dict(context.get("metadata", {})).get("environment_state"))
    metadata_trace = _as_dict(metadata_state.get("orchestration_trace"))
    if metadata_trace:
        payloads.append(metadata_trace)
    replay_metadata = _as_dict(metadata_state.get("world_orchestration_replay"))
    replay_metadata_trace = _as_dict(replay_metadata.get("orchestration_trace"))
    if replay_metadata_trace:
        payloads.append(replay_metadata_trace)

    for artifact in _as_list(context.get("artifacts", [])):
        artifact_type = str(_get(artifact, "type", "") or "").lower()
        if artifact_type != "trace":
            continue
        data = _as_dict(_get(artifact, "data", {}))
        metadata = _as_dict(_get(artifact, "metadata", {}))
        if _looks_like_orchestration_trace(data, metadata):
            payloads.append(data)
        elif str(data.get("kind") or metadata.get("kind") or "").lower() == "world_orchestration_replay":
            replay_trace = _as_dict(data.get("orchestration_trace"))
            if replay_trace:
                payloads.append(replay_trace)

    for event in _as_list(context.get("events", [])):
        event_type = str(_get(event, "type", "") or "").lower()
        name = str(_get(event, "name", "") or "").lower()
        payload = _as_dict(_get(event, "payload", {}))
        metadata = _as_dict(_get(event, "metadata", {}))
        if _looks_like_orchestration_trace(payload, metadata):
            payloads.append(payload)
        elif str(payload.get("kind") or "").lower() == "world_orchestration_replay":
            replay_trace = _as_dict(payload.get("orchestration_trace"))
            if replay_trace:
                payloads.append(replay_trace)
        elif "orchestration_step" in event_type:
            payloads.append({"kind": "orchestration_trace", "steps": [payload]})
        elif "orchestration" in event_type or "workflow" in event_type:
            wrapped = {"kind": "orchestration_trace", "events": [payload], "signals": [event_type, name]}
            if payload:
                wrapped["steps"] = [payload]
            payloads.append(wrapped)
    return [payload for payload in payloads if payload]


def _looks_like_orchestration_trace(data: Mapping[str, Any], metadata: Mapping[str, Any]) -> bool:
    kind = str(data.get("kind") or metadata.get("kind") or "").lower()
    if kind == "orchestration_trace":
        return True
    if kind in {
        "world_orchestration_replay",
        "world_attack_replay",
        "world_contract",
        "adversarial_attack_pack",
    }:
        return False
    return any(key in data for key in ("nodes", "edges", "steps", "summary")) and any(
        token in _stringify(data).lower() or token in _stringify(metadata).lower()
        for token in ("orchestration", "workflow", "route", "handoff", "retry")
    )


def _merge_orchestration_trace_payload(observed: set[str], payload: Mapping[str, Any]) -> None:
    if payload.get("nodes"):
        observed.add("node")
    if payload.get("edges"):
        observed.add("route")
    if payload.get("steps"):
        observed.add("step")
    if payload.get("state"):
        observed.add("state")
    for signal in _as_list(payload.get("signals", [])):
        _add_orchestration_trace_key(observed, str(signal))
    for collection_name in ("nodes", "edges", "steps", "events"):
        for item in _as_list(payload.get(collection_name, [])):
            item_dict = _as_dict(item)
            for key in ("type", "name", "node", "status", "event", "method"):
                _add_orchestration_trace_key(observed, str(item_dict.get(key, "")))
            for signal in _as_list(item_dict.get("signals", [])):
                _add_orchestration_trace_key(observed, str(signal))
            if item_dict.get("error"):
                observed.add("error")
            if item_dict.get("latency_ms") is not None:
                observed.add("latency")
            if item_dict.get("cost") not in (None, "", [], {}):
                observed.add("cost")
            if item_dict.get("recovered") is True:
                observed.add("recovered")
            if (_as_int(item_dict.get("attempt")) or 0) > 1:
                observed.add("retry")
    summary = _as_dict(payload.get("summary"))
    if (_as_int(summary.get("retry_count")) or 0) > 0:
        observed.add("retry")
    if (_as_int(summary.get("recovered_failures")) or 0) > 0:
        observed.add("recovered")
    if (_as_int(summary.get("failure_count")) or 0) > 0:
        observed.add("error")
    for count_key, signal in {
        "spawn_count": "spawn",
        "delegation_count": "delegate",
        "communication_count": "communicate",
        "aggregation_count": "aggregate",
        "stop_count": "stop",
    }.items():
        if (_as_int(summary.get(count_key)) or 0) > 0:
            observed.add(signal)
    if summary.get("total_latency_ms") is not None:
        observed.add("latency")
    if summary.get("total_cost") is not None:
        observed.add("cost")


